INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('379e0b34-0454-41ea-b078-242e248a40d1', '57325d3b-bd3c-5122-9ef7-88c0a197419b', 'මුවහත් කිරීමේ දී පිහියේ බර අඩු වීම යි.', 'මුවහත් කිරීමේ දී පිහියේ බර අඩු වීම යි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f0e96191-4ac2-5100-b549-509f7516f37a', 'dc80d607-0beb-535c-985b-9d06d2ba321c', 9, '<p>X මූලද්‍රව්‍යය ඔක්සිජන් සමග සාදන සංයෝගයේ සූත්‍රය XO වන අතර Y මූල ද්‍රව්‍යය සෝඩියම් සමග සාදන සංයෝගයේ සූත්‍රය NaY වේ.<br><br>X හා Y සංයෝජනයෙන් සෑදෙන සංයෝගයේ සූත්‍රය කුමක්ක්ද?</p>', '<p>X මූලද්‍රව්‍යය ඔක්සිජන් සමග සාදන සංයෝගයේ සූත්‍රය XO වන අතර Y මූල ද්‍රව්‍යය සෝඩියම් සමග සාදන සංයෝගයේ සූත්‍රය NaY වේ.<br><br>X හා Y සංයෝජනයෙන් සෑදෙන සංයෝගයේ සූත්‍රය කුමක්ක්ද?</p>', NULL, 'ඔක්සිජන්හි සංයුජතාව 2 කි. $XO$ සෑදීමට නම් X හි සංයුජතාව ද 2 විය යුතුය. $Na$ හි සංයුජතාව 1 කි. $NaY$ සෑදීමට නම් Y හි සංයුජතාව ද 1 විය යුතුය. X(2) සහ Y(1) එක් වී සංයෝගයක් සෑදීමේදී හරස් ගුණ කිරීමෙන් $XY_2$ සෑදේ.', 'ඔක්සිජන්හි සංයුජතාව 2 කි. $XO$ සෑදීමට නම් X හි සංයුජතාව ද 2 විය යුතුය. $Na$ හි සංයුජතාව 1 කි. $NaY$ සෑදීමට නම් Y හි සංයුජතාව ද 1 විය යුතුය. X(2) සහ Y(1) එක් වී සංයෝගයක් සෑදීමේදී හරස් ගුණ කිරීමෙන් $XY_2$ සෑදේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
