INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1a321898-87ef-4708-a293-9dd91da4ef12', '95e425c0-b3e8-5b80-94b0-474869a67df4', 'එය හරහා යෙදෙන විභව අන්තරය මත රඳා පවතී.', 'එය හරහා යෙදෙන විභව අන්තරය මත රඳා පවතී.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('341498c0-af08-50d0-be57-bcdde266e132', 'dc80d607-0beb-535c-985b-9d06d2ba321c', 13, '<p>කාබන් ඩයොක්සයිඩ් සහ හයිඩ්රජන් යන වායුවල නියැදි දෙකක් වායු සරාවලට රැස් කර ගැනීම සඳහා විසර්ජක නළ පිහිටුවිය යුතු නිවැරදි ආකාරය මින් කුමක්ද?</p>', '<p>කාබන් ඩයොක්සයිඩ් සහ හයිඩ්රජන් යන වායුවල නියැදි දෙකක් වායු සරාවලට රැස් කර ගැනීම සඳහා විසර්ජක නළ පිහිටුවිය යුතු නිවැරදි ආකාරය මින් කුමක්ද?</p>', NULL, 'කාබන් ඩයොක්සයිඩ් ($CO_2$) වාතයට වඩා බරින් වැඩි බැවින් එය වාතය උඩුකුරු විස්ථාපනයෙන් (වායු සරාව උඩුකුරුව තබා) එකතු කර ගනී. හයිඩ්රජන් ($H_2$) වාතයට වඩා සැහැල්ලු බැවින් එය වාතය යටිකුරු විස්ථාපනයෙන් (වායු සරාව යටිකුරුව තබා) එකතු කර ගනී.', 'කාබන් ඩයොක්සයිඩ් ($CO_2$) වාතයට වඩා බරින් වැඩි බැවින් එය වාතය උඩුකුරු විස්ථාපනයෙන් (වායු සරාව උඩුකුරුව තබා) එකතු කර ගනී. හයිඩ්රජන් ($H_2$) වාතයට වඩා සැහැල්ලු බැවින් එය වාතය යටිකුරු විස්ථාපනයෙන් (වායු සරාව යටිකුරුව තබා) එකතු කර ගනී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
