INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dfa90636-9227-410f-919e-3582facf97a2', 'a44a440c-3aa6-5e57-8e17-c1e565f3fd8c', 'ප්‍රතිබිම්බය පාර්ශ්වික ව අපවර්තනය වී පවතී.', 'ප්‍රතිබිම්බය පාර්ශ්වික ව අපවර්තනය වී පවතී.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('feb6102b-ff40-4fc6-b04c-9585181ccf66', 'a44a440c-3aa6-5e57-8e17-c1e565f3fd8c', 'ප්‍රතිබිම්බ දුර දර්පණයේ ජ්‍යාමිතික හැඩය මත රඳා පවතී.', 'ප්‍රතිබිම්බ දුර දර්පණයේ ජ්‍යාමිතික හැඩය මත රඳා පවතී.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('00a504f3-cdd2-51ab-a975-95d5d0304812', 'dc80d607-0beb-535c-985b-9d06d2ba321c', 20, '<p>පණිවුඩ හුවමාරු චන්ද්‍රිකාවක් පොළොව මට්ටමේ සිට 36 000 kmක් උසින් කක්ෂගත කර ඇත.<br>පොළොව මත පිහිටි සම්ප්‍රේෂණාගාරයක සිට නිකුත් කරන රේඩියෝ තරංගයක් චන්ද්‍රිකාව වෙත ළඟා වීමට ගත වන කාලය තත්පර වලින් කොපමණ ද?<br>(වාතයේ රේඩියෝ තරංග වේගය $3.0\times10^{8}ms^{-1}$ වේ.)</p>', '<p>පණිවුඩ හුවමාරු චන්ද්‍රිකාවක් පොළොව මට්ටමේ සිට 36 000 kmක් උසින් කක්ෂගත කර ඇත.<br>පොළොව මත පිහිටි සම්ප්‍රේෂණාගාරයක සිට නිකුත් කරන රේඩියෝ තරංගයක් චන්ද්‍රිකාව වෙත ළඟා වීමට ගත වන කාලය තත්පර වලින් කොපමණ ද?<br>(වාතයේ රේඩියෝ තරංග වේගය $3.0\times10^{8}ms^{-1}$ වේ.)</p>', NULL, 'වේගය = දුර / කාලය $\rightarrow$ කාලය = දුර / වේගය.<br>දුර (මීටර වලින්) = $36000 km = 36000 \times 1000 m = 3.6 \times 10^7 m$.<br>වේගය = $3.0 \times 10^8 ms^{-1}$.<br>ගතවන කාලය = $\frac{3.6 \times 10^7}{3.0 \times 10^8}$ s.', 'වේගය = දුර / කාලය $\rightarrow$ කාලය = දුර / වේගය.<br>දුර (මීටර වලින්) = $36000 km = 36000 \times 1000 m = 3.6 \times 10^7 m$.<br>වේගය = $3.0 \times 10^8 ms^{-1}$.<br>ගතවන කාලය = $\frac{3.6 \times 10^7}{3.0 \times 10^8}$ s.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
