INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ee20f99a-9afb-4c54-850c-0f6868660310', 'be58e773-ac0d-5e87-a570-6312d9911b7c', 'A, B සහ C යන සියල්ල ම ය.', 'A, B සහ C යන සියල්ල ම ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('566e59d6-f44d-53d3-9700-859c0de8f1aa', 'dc80d607-0beb-535c-985b-9d06d2ba321c', 23, '<p>P හා Q යන ලෝහ තනුක අම්ල සමග ප්‍රතික්‍රියා කර හයිඩ්රජන් වායුව නිදහස් කරන අතර R ලෝහය තනුක අම්ල සමග හයිඩ්රජන් පිට නො කරයි.<br>P ට Q හි ලවණ ද්‍රාවණයකින් Q ප්‍රතිස්ථාපනය කළ නොහැකි ය. P, Q, R ලෝහ සක්‍රියතා ශ්‍රේණියේ පිහිටන අනුපිළිවෙළ කුමක්ද?</p>', '<p>P හා Q යන ලෝහ තනුක අම්ල සමග ප්‍රතික්‍රියා කර හයිඩ්රජන් වායුව නිදහස් කරන අතර R ලෝහය තනුක අම්ල සමග හයිඩ්රජන් පිට නො කරයි.<br>P ට Q හි ලවණ ද්‍රාවණයකින් Q ප්‍රතිස්ථාපනය කළ නොහැකි ය. P, Q, R ලෝහ සක්‍රියතා ශ්‍රේණියේ පිහිටන අනුපිළිවෙළ කුමක්ද?</p>', NULL, 'P සහ Q අම්ල සමග ප්‍රතික්‍රියා කරන බැවින් ඒවා R ට වඩා සක්‍රිය වේ (P, Q > R). P ට Q හි ලවණ ද්‍රාවණයකින් Q ප්‍රතිස්ථාපනය කළ නොහැකි බැවින් Q හි සක්‍රියතාව P ට වඩා වැඩිය (Q > P). ඒ අනුව සක්‍රියතාව වැඩිම Q වන අතර, අනුපිළිවෙල Q, P, R වේ.', 'P සහ Q අම්ල සමග ප්‍රතික්‍රියා කරන බැවින් ඒවා R ට වඩා සක්‍රිය වේ (P, Q > R). P ට Q හි ලවණ ද්‍රාවණයකින් Q ප්‍රතිස්ථාපනය කළ නොහැකි බැවින් Q හි සක්‍රියතාව P ට වඩා වැඩිය (Q > P). ඒ අනුව සක්‍රියතාව වැඩිම Q වන අතර, අනුපිළිවෙල Q, P, R වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
