INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c9bdf2a7-c211-5893-96d3-8f972ccdaa93', 'dc80d607-0beb-535c-985b-9d06d2ba321c', 31, '<p>විදුලි තාපකයක ක්ෂමතාව 1 000 W වේ.<br>මෙම තාපකය පැය 2 ක කාලයක් ක්‍රියාත්මක වීමේ දී වැය වන විද්‍යුත් ශක්ති ප්‍රමාණය,</p>', '<p>විදුලි තාපකයක ක්ෂමතාව 1 000 W වේ.<br>මෙම තාපකය පැය 2 ක කාලයක් ක්‍රියාත්මක වීමේ දී වැය වන විද්‍යුත් ශක්ති ප්‍රමාණය,</p>', NULL, 'විද්‍යුත් ශක්තිය (kWh) = ජවය (kW) $\times$ කාලය (h).<br>$1000 W$ යනු $1 kW$ වේ.<br>ශක්තිය = $1 kW \times 2 h = 2 kWh$.', 'විද්‍යුත් ශක්තිය (kWh) = ජවය (kW) $\times$ කාලය (h).<br>$1000 W$ යනු $1 kW$ වේ.<br>ශක්තිය = $1 kW \times 2 h = 2 kWh$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
