INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a727f730-c69c-5d65-a84d-2ef495f6c1f4', 'dc80d607-0beb-535c-985b-9d06d2ba321c', 36, '<p>හයිඩ්රජන් ක්ලෝරයිඩ්වල හා ජලයේ තාපාංක පිළිවෙළින් $-85^{\circ}C$ හා $100^{\circ}C$ වේ.<br>මේ වෙනසට හේතුව පැහැදිලි කෙරෙන්නේ පහත කුමන ප්‍රකාශයෙන්ද?</p>', '<p>හයිඩ්රජන් ක්ලෝරයිඩ්වල හා ජලයේ තාපාංක පිළිවෙළින් $-85^{\circ}C$ හා $100^{\circ}C$ වේ.<br>මේ වෙනසට හේතුව පැහැදිලි කෙරෙන්නේ පහත කුමන ප්‍රකාශයෙන්ද?</p>', NULL, 'අණුවක තාපාංකය රඳා පවතින්නේ අණු අතර ඇති අන්තර් අණුක බලවල ප්‍රබලතාවය මතය. ජල අණු අතර ප්‍රබල හයිඩ්රජන් බන්ධන පවතින අතර, $HCl$ අණු අතර ඇත්තේ ඊට වඩා දුර්වල ද්වීධ්‍රැව-ද්වීධ්‍රැව ආකර්ෂණ බල වේ. එබැවින් ජලයේ තාපාංකය ඉහළය.', 'අණුවක තාපාංකය රඳා පවතින්නේ අණු අතර ඇති අන්තර් අණුක බලවල ප්‍රබලතාවය මතය. ජල අණු අතර ප්‍රබල හයිඩ්රජන් බන්ධන පවතින අතර, $HCl$ අණු අතර ඇත්තේ ඊට වඩා දුර්වල ද්වීධ්‍රැව-ද්වීධ්‍රැව ආකර්ෂණ බල වේ. එබැවින් ජලයේ තාපාංකය ඉහළය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5ab47655-695e-4bf7-9e48-1aae46ef3e25', 'a727f730-c69c-5d65-a84d-2ef495f6c1f4', 'හයිඩ්රජන් ක්ලෝරයිඩ් අණු අතර අන්තර් අණුක බල, ජල අණු අතර අන්තර් අණුක බල වලට වඩා දුර්වල ය.', 'හයිඩ්රජන් ක්ලෝරයිඩ් අණු අතර අන්තර් අණුක බල, ජල අණු අතර අන්තර් අණුක බල වලට වඩා දුර්වල ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2fb529a4-0eae-47f2-b6ce-4d36c694572f', 'a727f730-c69c-5d65-a84d-2ef495f6c1f4', 'හයිඩ්රජන් ක්ලෝරයිඩ්වල සාපේක්ෂ අණුක ස්කන්ධය ජලයේ සාපේක්ෂ අණුක ස්කන්ධයට වඩා වැඩිය.', 'හයිඩ්රජන් ක්ලෝරයිඩ්වල සාපේක්ෂ අණුක ස්කන්ධය ජලයේ සාපේක්ෂ අණුක ස්කන්ධයට වඩා වැඩිය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('aa2acfe4-902f-4ce1-85e6-b3f23cae2b23', 'a727f730-c69c-5d65-a84d-2ef495f6c1f4', 'අණුවල පරමාණු අතර සහ බන්ධන, හයිඩ්රජන් ක්ලෝරයිඩ් වලට වඩා ජලයේ ප්‍රබල ය.', 'අණුවල පරමාණු අතර සහ බන්ධන, හයිඩ්රජන් ක්ලෝරයිඩ් වලට වඩා ජලයේ ප්‍රබල ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('50d4c3a9-f88f-4636-a8d1-142b1c4d5860', 'a727f730-c69c-5d65-a84d-2ef495f6c1f4', 'ජල අණු ධ්‍රැවීය වන අතර හයිඩ්රජන් ක්ලෝරයිඩ් අණු නිර්ධ්‍රැවීය ය.', 'ජල අණු ධ්‍රැවීය වන අතර හයිඩ්රජන් ක්ලෝරයිඩ් අණු නිර්ධ්‍රැවීය ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9cc5104a-52cf-5a2c-88eb-ed15af120bce', 'dc80d607-0beb-535c-985b-9d06d2ba321c', 37, '<p>දුනු තරාදියක එල්ලන ලද සින්ක් තහඩු කැබැල්ලක් හයිඩ්රොක්ලෝරික් අම්ල ද්‍රාවණයක ගිල්වා ප්‍රතික්‍රියා වීමට සලසන ලද අතර ප්‍රතික්‍රියාව ආරම්භ වී මඳ වේලාවකට පසු එම අම්ල ද්‍රාවණයෙන් තවත් ප්‍රමාණයක් ප්‍රතික්‍රියා මිශ්‍රණයට එක් කරන ලදි.<br>දුනු තරාදි පාඨාංකය (m) කාලයට (t) එරෙහි ව ප්‍රස්තාර ගත කළ හොත් මින් කුමන ප්‍රස්තාරය ලැබීමට වැඩියෙන්ම ඉඩ තිබේද?</p>', '<p>දුනු තරාදියක එල්ලන ලද සින්ක් තහඩු කැබැල්ලක් හයිඩ්රොක්ලෝරික් අම්ල ද්‍රාවණයක ගිල්වා ප්‍රතික්‍රියා වීමට සලසන ලද අතර ප්‍රතික්‍රියාව ආරම්භ වී මඳ වේලාවකට පසු එම අම්ල ද්‍රාවණයෙන් තවත් ප්‍රමාණයක් ප්‍රතික්‍රියා මිශ්‍රණයට එක් කරන ලදි.<br>දුනු තරාදි පාඨාංකය (m) කාලයට (t) එරෙහි ව ප්‍රස්තාර ගත කළ හොත් මින් කුමන ප්‍රස්තාරය ලැබීමට වැඩියෙන්ම ඉඩ තිබේද?</p>', NULL, 'සින්ක් තහඩුව අම්ලය සමග ප්‍රතික්‍රියා කර දිය වී යන බැවින් එහි ස්කන්ධය ක්‍රමයෙන් අඩුවේ. අම්ලය අවසන් වූ විට ප්‍රතික්‍රියාව නැවතී ස්කන්ධය නියතව පවතී (තිරස් කොටස). නැවත අම්ලය එක් කළ විට ඉතිරි සින්ක් ප්‍රමාණය ද ප්‍රතික්‍රියා කර ස්කන්ධය තවදුරටත් අඩු වේ.', 'සින්ක් තහඩුව අම්ලය සමග ප්‍රතික්‍රියා කර දිය වී යන බැවින් එහි ස්කන්ධය ක්‍රමයෙන් අඩුවේ. අම්ලය අවසන් වූ විට ප්‍රතික්‍රියාව නැවතී ස්කන්ධය නියතව පවතී (තිරස් කොටස). නැවත අම්ලය එක් කළ විට ඉතිරි සින්ක් ප්‍රමාණය ද ප්‍රතික්‍රියා කර ස්කන්ධය තවදුරටත් අඩු වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
