INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('09c77590-d5fd-467f-a11c-9ee1b552f298', '9cc5104a-52cf-5a2c-88eb-ed15af120bce', 'ස්කන්ධය m අඩුවී, නියතව පැවතී, ශීඝ්‍රයෙන් පහත වැටී ශුන්‍ය වන ප්‍රස්තාරයක්
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('36b25597-40ba-5f9e-a3ec-7ab6e7d6ba6b', 'dc80d607-0beb-535c-985b-9d06d2ba321c', 38, '<p>පහත සඳහන් ප්‍රකාශ අතරින් වැරදි ප්‍රකාශය කුමක්ද?</p>', '<p>පහත සඳහන් ප්‍රකාශ අතරින් වැරදි ප්‍රකාශය කුමක්ද?</p>', NULL, 'ක්ලෝරොෆ්ලුවොරොකාබන (CFC) ප්‍රධාන වශයෙන් බලපාන්නේ ඕසෝන් ස්තරය හායනය වීම සඳහාය. අම්ල වැසි සඳහා ප්‍රධාන වශයෙන් හේතු වන්නේ සල්ෆර් ඩයොක්සයිඩ් ($SO_2$) සහ නයිට්රජන් ඔක්සයිඩ වායුන්‍ ය. එබැවින් පළමු ප්‍රකාශය වැරදිය.', 'ක්ලෝරොෆ්ලුවොරොකාබන (CFC) ප්‍රධාන වශයෙන් බලපාන්නේ ඕසෝන් ස්තරය හායනය වීම සඳහාය. අම්ල වැසි සඳහා ප්‍රධාන වශයෙන් හේතු වන්නේ සල්ෆර් ඩයොක්සයිඩ් ($SO_2$) සහ නයිට්රජන් ඔක්සයිඩ වායුන්‍ ය. එබැවින් පළමු ප්‍රකාශය වැරදිය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('34af181e-e9c6-4067-ae08-a5695e146a1a', '36b25597-40ba-5f9e-a3ec-7ab6e7d6ba6b', 'වායුගෝලයට ක්ලෝරොෆ්ලුවොරොකාබන එක් වීමෙන් අම්ල වැසි ඇති වේ.', 'වායුගෝලයට ක්ලෝරොෆ්ලුවොරොකාබන එක් වීමෙන් අම්ල වැසි ඇති වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fb5f5045-abb1-4df6-92c5-978268e7cab5', '36b25597-40ba-5f9e-a3ec-7ab6e7d6ba6b', 'හරිතාගාර ආචරණය ජීවය පවත්වා ගෙන යාමට අත්‍යවශ්‍යය.', 'හරිතාගාර ආචරණය ජීවය පවත්වා ගෙන යාමට අත්‍යවශ්‍යය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('29814f2b-5d74-4e25-9aba-be976cce6c82', '36b25597-40ba-5f9e-a3ec-7ab6e7d6ba6b', 'ගෝලීය උණුසුම් වීම කෙරෙහි හරිතාගාර ආචරණය බලපායි.', 'ගෝලීය උණුසුම් වීම කෙරෙහි හරිතාගාර ආචරණය බලපායි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('67d7f8cd-c5a0-416b-b571-377f5bc83135', '36b25597-40ba-5f9e-a3ec-7ab6e7d6ba6b', 'නයිට්රජන්හි ඔක්සයිඩ ඕසෝන් ස්තරය හායනය කෙරෙහි බලපායි.', 'නයිට්රජන්හි ඔක්සයිඩ ඕසෝන් ස්තරය හායනය කෙරෙහි බලපායි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('be5f7b0f-84f4-5d56-87d3-356b45e00370', 'dc80d607-0beb-535c-985b-9d06d2ba321c', 39, '<p>මිනිස් බලපෑම අවම වන්නේ පහත කුමන ආපදා තත්ත්වය කෙරෙහි ද?</p>', '<p>මිනිස් බලපෑම අවම වන්නේ පහත කුමන ආපදා තත්ත්වය කෙරෙහි ද?</p>', NULL, 'සුනාමි යනු මුහුදු පත්ලේ ඇතිවන භූමිකම්පා, නායයෑම් හෝ ගිනිකඳු පිපිරීම් වැනි ස්වාභාවික හේතූන් මත හටගන්නා ආපදාවක් බැවින් ඒ සඳහා මිනිස් බලපෑම අවම වේ. අනෙකුත් සියලුම ආපදා තත්ත්වයන් සඳහා මිනිස් ක්‍රියාකාරකම් සෘජුවම බලපායි.', 'සුනාමි යනු මුහුදු පත්ලේ ඇතිවන භූමිකම්පා, නායයෑම් හෝ ගිනිකඳු පිපිරීම් වැනි ස්වාභාවික හේතූන් මත හටගන්නා ආපදාවක් බැවින් ඒ සඳහා මිනිස් බලපෑම අවම වේ. අනෙකුත් සියලුම ආපදා තත්ත්වයන් සඳහා මිනිස් ක්‍රියාකාරකම් සෘජුවම බලපායි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
