INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e2d28883-46df-4167-8caa-058dd3506c13', 'be5f7b0f-84f4-5d56-87d3-356b45e00370', 'ආගන්තුක ආක්‍රමණික ශාක පැතිරීම', 'ආගන්තුක ආක්‍රමණික ශාක පැතිරීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6afff102-23ea-4cb7-ad21-0ebe08d96ae2', 'be5f7b0f-84f4-5d56-87d3-356b45e00370', 'වන සතුන් ජනාවාස ආක්‍රමණය කිරීම', 'වන සතුන් ජනාවාස ආක්‍රමණය කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('607d7a68-91d9-5474-b78a-d560e24ca67a', 'dc80d607-0beb-535c-985b-9d06d2ba321c', 40, '<p>සාම්ප්‍රදායික වැවක වැව් බැම්ම සේදී යාම වැළැක්වීම සඳහා ඇති අංගය කුමක්ද?</p>', '<p>සාම්ප්‍රදායික වැවක වැව් බැම්ම සේදී යාම වැළැක්වීම සඳහා ඇති අංගය කුමක්ද?</p>', NULL, 'වැවේ ජල තරංග (රළ) වැදී වැව් බැම්ම සේදී යාම (ඛාදනය වීම) වැළැක්වීම සඳහා බැම්මේ ඇතුළු පැත්තේ ගල් අතුරා සකස් කර ඇති කොටස රළපනාව ලෙස හැඳින්වේ.', 'වැවේ ජල තරංග (රළ) වැදී වැව් බැම්ම සේදී යාම (ඛාදනය වීම) වැළැක්වීම සඳහා බැම්මේ ඇතුළු පැත්තේ ගල් අතුරා සකස් කර ඇති කොටස රළපනාව ලෙස හැඳින්වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
