INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0436f9ce-89d8-5ae8-8540-8779c3fd1047', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 2, '<p>In a vernier calliper a length of 19 main scale divisions is equally divided into 20 vernier scale divisions.<br><br>What should be the length of a main scale division in order to have a least count of 0.025 mm?</p>', '<p>In a vernier calliper a length of 19 main scale divisions is equally divided into 20 vernier scale divisions.<br><br>What should be the length of a main scale division in order to have a least count of 0.025 mm?</p>', NULL, 'Least count (LC) = 1 MSD - 1 VSD.<br>Since 20 VSD = 19 MSD, 1 VSD = $19/20$ MSD.<br>LC = 1 MSD - $19/20$ MSD = $1/20$ MSD.<br>Given LC = 0.025 mm, so $1/20$ MSD = 0.025 mm $\implies$ MSD = $20 \times 0.025 = 0.5$ mm.', 'Least count (LC) = 1 MSD - 1 VSD.<br>Since 20 VSD = 19 MSD, 1 VSD = $19/20$ MSD.<br>LC = 1 MSD - $19/20$ MSD = $1/20$ MSD.<br>Given LC = 0.025 mm, so $1/20$ MSD = 0.025 mm $\implies$ MSD = $20 \times 0.025 = 0.5$ mm.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
