INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('405d3636-f4a6-5402-950b-c56beab34e6b', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 5, '<p>The mean kinetic energy of an ideal gas depends on its</p>', '<p>The mean kinetic energy of an ideal gas depends on its</p>', NULL, 'The mean kinetic energy of an ideal gas molecule is given by $E = \frac{3}{2}kT$, which shows it depends directly and solely on the absolute temperature $T$.', 'The mean kinetic energy of an ideal gas molecule is given by $E = \frac{3}{2}kT$, which shows it depends directly and solely on the absolute temperature $T$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
