INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('784aef13-9ff5-55d9-a920-507f371beca0', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 6, '<p>A block of mass $M$ moving at velocity $2v$ on a flat frictionless surface makes a perfect inelastic collision with another block of mass $M$ moving at velocity $v$ along the same direction. What is the velocity of the first block after the collision?</p>', '<p>A block of mass $M$ moving at velocity $2v$ on a flat frictionless surface makes a perfect inelastic collision with another block of mass $M$ moving at velocity $v$ along the same direction. What is the velocity of the first block after the collision?</p>', NULL, 'By conservation of linear momentum: $M(2v) + M(v) = (M + M)V_f$<br>$3Mv = 2MV_f \implies V_f = \frac{3}{2}v$. Since it is a perfect inelastic collision, both blocks move together with this velocity.', 'By conservation of linear momentum: $M(2v) + M(v) = (M + M)V_f$<br>$3Mv = 2MV_f \implies V_f = \frac{3}{2}v$. Since it is a perfect inelastic collision, both blocks move together with this velocity.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
