INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('365f8122-38b7-530c-a321-1af9e65a8c76', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 8, '<p>What is the charge of a down quark ($d$)? (The elementary charge is $e$.)</p>', '<p>What is the charge of a down quark ($d$)? (The elementary charge is $e$.)</p>', NULL, 'In the Standard Model of particle physics, a down quark ($d$) carries a fractional electric charge of $-\frac{1}{3}e$.', 'In the Standard Model of particle physics, a down quark ($d$) carries a fractional electric charge of $-\frac{1}{3}e$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
