INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5e7bf892-ac0c-529a-b05d-d6f570a06c0c', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 11, '<p>An object is placed in front of a concave lens as shown in the figure. The paths of the refracted rays emitting from point $A$ of the object are</p>', '<p>An object is placed in front of a concave lens as shown in the figure. The paths of the refracted rays emitting from point $A$ of the object are</p>', NULL, 'For a concave lens, incident rays parallel to the principal axis diverge, appearing to originate from the principal focus (ray P). Rays passing through the optical center pass undeviated (ray R). Ray Q represents a ray directed towards the virtual focus on the other side, which emerges parallel to the principal axis. Thus, P, Q, and R are correct.', 'For a concave lens, incident rays parallel to the principal axis diverge, appearing to originate from the principal focus (ray P). Rays passing through the optical center pass undeviated (ray R). Ray Q represents a ray directed towards the virtual focus on the other side, which emerges parallel to the principal axis. Thus, P, Q, and R are correct.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
