INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('514e936f-cd35-5edb-94e1-2e0ba82be774', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 12, '<p>The displacement-time ($s-t$) graph for the motion of an object is shown in the figure. The corresponding velocity-time ($v-t$) graph would be best represented by,</p>', '<p>The displacement-time ($s-t$) graph for the motion of an object is shown in the figure. The corresponding velocity-time ($v-t$) graph would be best represented by,</p>', NULL, 'The gradient of the $s-t$ graph gives the velocity. The curve shows a decreasing positive gradient, then zero gradient, then increasing positive gradient. This translates to a velocity that decreases to zero, remains at zero, and then increases.', 'The gradient of the $s-t$ graph gives the velocity. The curve shows a decreasing positive gradient, then zero gradient, then increasing positive gradient. This translates to a velocity that decreases to zero, remains at zero, and then increases.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
