INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3421c08a-8af2-54f7-851d-b2a79253acc0', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 13, '<p>An object A moving in a circular path at a uniform angular velocity is shown in the figure. The variation of displacement ($x$) and velocity ($v$) of the point $P$ of projection of the object on the $X$-axis with time ($t$) is best represented by,</p>', '<p>An object A moving in a circular path at a uniform angular velocity is shown in the figure. The variation of displacement ($x$) and velocity ($v$) of the point $P$ of projection of the object on the $X$-axis with time ($t$) is best represented by,</p>', NULL, 'The projection of uniform circular motion on a diameter exhibits Simple Harmonic Motion (SHM). Displacement $x$ will be a cosine curve, and velocity $v$ will be a sine curve (its derivative). Their phase difference is $\frac{\pi}{2}$.', 'The projection of uniform circular motion on a diameter exhibits Simple Harmonic Motion (SHM). Displacement $x$ will be a cosine curve, and velocity $v$ will be a sine curve (its derivative). Their phase difference is $\frac{\pi}{2}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
