INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('51e4d0eb-335a-5f66-95a9-3f02419cb354', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 14, '<p>Water rises in a long vertical capillary tube up to a height of 2.0 cm. When the tube is inclined at an angle 60° with the vertical, what is the length of the water column in the tube?</p>', '<p>Water rises in a long vertical capillary tube up to a height of 2.0 cm. When the tube is inclined at an angle 60° with the vertical, what is the length of the water column in the tube?</p>', NULL, 'The vertical height of the liquid column remains the same irrespective of the inclination. Therefore, $h = l \cos \theta \implies l = \frac{h}{\cos 60^{\circ}} = \frac{2.0}{0.5} = 4.0$ cm.', 'The vertical height of the liquid column remains the same irrespective of the inclination. Therefore, $h = l \cos \theta \implies l = \frac{h}{\cos 60^{\circ}} = \frac{2.0}{0.5} = 4.0$ cm.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
