INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e9222880-ffb3-5b0e-9d9e-6431f0aa6022', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 15, '<p>Consider the following statements regarding the moment of inertia of a body.<br>(A) It depends on mass of the body.<br>(B) It depends on mass distribution of the body.<br>(C) It depends on angular velocity of the body.<br><br>Of the above statements,</p>', '<p>Consider the following statements regarding the moment of inertia of a body.<br>(A) It depends on mass of the body.<br>(B) It depends on mass distribution of the body.<br>(C) It depends on angular velocity of the body.<br><br>Of the above statements,</p>', NULL, 'Moment of inertia ($I = \sum mr^2$) depends strictly on the total mass of the body and how that mass is distributed relative to the axis of rotation. It does not depend on the kinematic state, like angular velocity.', 'Moment of inertia ($I = \sum mr^2$) depends strictly on the total mass of the body and how that mass is distributed relative to the axis of rotation. It does not depend on the kinematic state, like angular velocity.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
