INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('884b5f97-088a-5a55-9f5a-060f30b50be3', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 16, '<p>A liquid of density $\rho$ flowing at speed $3v$ through a horizontal tube of cross-sectional area $A$ strikes a vertical wall perpendicularly and flows down along the wall without recoil. The force exerted on the wall by the liquid is</p>', '<p>A liquid of density $\rho$ flowing at speed $3v$ through a horizontal tube of cross-sectional area $A$ strikes a vertical wall perpendicularly and flows down along the wall without recoil. The force exerted on the wall by the liquid is</p>', NULL, 'Force exerted is the rate of change of momentum. $F = \frac{dm}{dt} \times \Delta v$. The mass flow rate $\frac{dm}{dt} = \rho A (3v)$. Change in velocity is $(3v - 0) = 3v$. Force = $\rho A (3v) \times 3v = 9\rho A v^2$.', 'Force exerted is the rate of change of momentum. $F = \frac{dm}{dt} \times \Delta v$. The mass flow rate $\frac{dm}{dt} = \rho A (3v)$. Change in velocity is $(3v - 0) = 3v$. Force = $\rho A (3v) \times 3v = 9\rho A v^2$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
