INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('85e7204c-ef0a-552c-9dc3-1274226a641a', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 18, '<p>A block placed on a horizontal frictionless table is attached to mass $m$ by a light inextensible string that passes over a pulley as shown in the figure. When released from rest, mass $m$ and the pulley accelerate. If the tensions in the sections in the string are $T_1$ and $T_2$ as marked, which of the following is true?</p>', '<p>A block placed on a horizontal frictionless table is attached to mass $m$ by a light inextensible string that passes over a pulley as shown in the figure. When released from rest, mass $m$ and the pulley accelerate. If the tensions in the sections in the string are $T_1$ and $T_2$ as marked, which of the following is true?</p>', NULL, 'Because the mass $m$ accelerates downwards, the net force is downwards: $mg - T_1 = ma$, so $mg > T_1$. Because the pulley is accelerating (it has mass/inertia), a net torque is required to rotate it, implying the tension pulling it ($T_1$) must be greater than the tension resisting it ($T_2$). Thus, $mg > T_1 > T_2$.', 'Because the mass $m$ accelerates downwards, the net force is downwards: $mg - T_1 = ma$, so $mg > T_1$. Because the pulley is accelerating (it has mass/inertia), a net torque is required to rotate it, implying the tension pulling it ($T_1$) must be greater than the tension resisting it ($T_2$). Thus, $mg > T_1 > T_2$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
