INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f46a6d14-2c0b-59b0-9ad7-e697b63b90a6', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 19, '<p>The variation of product ($PV$) of pressure and volume with pressure ($P$) for a fixed mass of an ideal gas at constant temperature is best represented by</p>', '<p>The variation of product ($PV$) of pressure and volume with pressure ($P$) for a fixed mass of an ideal gas at constant temperature is best represented by</p>', NULL, 'According to Boyle''s law, for a fixed mass of an ideal gas at constant temperature, $PV = \text{constant}$. Therefore, the graph of $PV$ against $P$ is a horizontal straight line parallel to the $P$-axis.', 'According to Boyle''s law, for a fixed mass of an ideal gas at constant temperature, $PV = \text{constant}$. Therefore, the graph of $PV$ against $P$ is a horizontal straight line parallel to the $P$-axis.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
