INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d1f60377-52b2-5fd6-b1ab-594193c3b198', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 22, '<p>If the doping concentrations of emitter, base and collector of a bipolar junction transistor are $n_E$, $n_B$ and $n_C$ respectively which of the following is true?</p>', '<p>If the doping concentrations of emitter, base and collector of a bipolar junction transistor are $n_E$, $n_B$ and $n_C$ respectively which of the following is true?</p>', NULL, 'In a BJT, the emitter is the most heavily doped region to inject a large number of charge carriers. The collector is moderately doped, and the base is very lightly doped to minimize recombination. Thus, $n_E > n_C > n_B$.', 'In a BJT, the emitter is the most heavily doped region to inject a large number of charge carriers. The collector is moderately doped, and the base is very lightly doped to minimize recombination. Thus, $n_E > n_C > n_B$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
