INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('77057d92-ff69-52ee-80ed-13364f2e238f', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 23, '<p>Consider the circuit shown in the figure. The internal resistance of the 12 V cell is negligible and the centre zero voltmeter is ideal. What is the value of the voltmeter reading?</p>', '<p>Consider the circuit shown in the figure. The internal resistance of the 12 V cell is negligible and the centre zero voltmeter is ideal. What is the value of the voltmeter reading?</p>', NULL, 'In a balanced or unbalanced Wheatstone bridge configuration without the specific resistance values, the potential difference is calculated using the voltage divider rule across the two parallel branches. The voltmeter measures the potential difference between the midpoints of these branches, yielding +5 V based on the correct option.', 'In a balanced or unbalanced Wheatstone bridge configuration without the specific resistance values, the potential difference is calculated using the voltage divider rule across the two parallel branches. The voltmeter measures the potential difference between the midpoints of these branches, yielding +5 V based on the correct option.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state =