INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cca97e68-387c-555d-8b25-d43376a71775', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 24, '<p>When a plate PQRST is hanging freely from point X it balances as shown figure (1). When hanging freely from point Y it balances as shown in figure (2). The centre of gravity of the plate is most likely to be found at</p>', '<p>When a plate PQRST is hanging freely from point X it balances as shown figure (1). When hanging freely from point Y it balances as shown in figure (2). The centre of gravity of the plate is most likely to be found at</p>', NULL, 'When an object hangs freely, its center of gravity always rests vertically below the pivot point. Plotting plumb lines from X and Y on the rigid body leads to an intersection at the true center of gravity.', 'When an object hangs freely, its center of gravity always rests vertically below the pivot point. Plotting plumb lines from X and Y on the rigid body leads to an intersection at the true center of gravity.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
