INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('74d284c4-ad36-5b91-a757-0933a6cb0e59', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 27, '<p>Consider the following statements made regarding electromagnetic (EM) waves.<br>(A) They can be transverse or longitudinal.<br>(B) They require a medium to propagate.<br>(C) They are not deflected by electric or magnetic field.<br><br>Of the above statements,</p>', '<p>Consider the following statements made regarding electromagnetic (EM) waves.<br>(A) They can be transverse or longitudinal.<br>(B) They require a medium to propagate.<br>(C) They are not deflected by electric or magnetic field.<br><br>Of the above statements,</p>', NULL, 'EM waves are strictly transverse (A is false), do not require a material medium to propagate as they can travel in a vacuum (B is false), and since they carry no net electric charge, they are not deflected by electric or magnetic fields (C is true).', 'EM waves are strictly transverse (A is false), do not require a material medium to propagate as they can travel in a vacuum (B is false), and since they carry no net electric charge, they are not deflected by electric or magnetic fields (C is true).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', upda