INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('14748fb6-4131-5950-8815-e5fb7669f821', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 32, '<p>Three capacitors each of capacitance $C$ are connected to a battery and a key $K$ as shown in the figure. Initially the key $K$ is closed. Once the capacitors are fully charged, the key $K$ is opened. If the potential difference across the battery is $V$, the total charge of the capacitors in the circuit is</p>', '<p>Three capacitors each of capacitance $C$ are connected to a battery and a key $K$ as shown in the figure. Initially the key $K$ is closed. Once the capacitors are fully charged, the key $K$ is opened. If the potential difference across the battery is $V$, the total charge of the capacitors in the circuit is</p>', NULL, 'Once a capacitor system reaches steady state and is fully charged, opening a switch that doesn''t provide a discharge path traps the accumulated charge on the plates. The total charge of the circuit remains unchanged.', 'Once a capacitor system reaches steady state and is fully charged, opening a switch that doesn''t provide a discharge path traps the accumulated charge on the plates. The total charge of the circuit remains unchanged.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
