INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e5a3d23c-a0f3-59ea-b325-336ac83cc4a3', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 33, '<p>Three long straight conducting wires A, B and C are kept at the three vertices of a square as shown in the figure. They are parallel to each other and carry equal currents of $I$ directed out of the plane of the paper. The direction of the resultant magnetic flux density at point D is given by,</p>', '<p>Three long straight conducting wires A, B and C are kept at the three vertices of a square as shown in the figure. They are parallel to each other and carry equal currents of $I$ directed out of the plane of the paper. The direction of the resultant magnetic flux density at point D is given by,</p>', NULL, 'By the Right Hand Grip Rule, the magnetic field at D from A points along ''b'', from C points along ''d'', and from B points along ''c''. The fields from A and C are equal in magnitude and perpendicular, meaning their vector sum points along the diagonal ''c'', perfectly aligning with and adding to the field produced by B.', 'By the Right Hand Grip Rule, the magnetic field at D from A points along ''b'', from C points along ''d'', and from B points along ''c''. The fields from A and C are equal in magnitude and perpendicular, meaning their vector sum points along the diagonal ''c'', perfectly aligning with and adding to the field produced by B.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
