INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('689aeb59-a70b-5ec2-9707-9bf32d4f5848', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 34, '<p>A uniform magnet field of flux density ($B$) 1 T and a uniform electric field of field intensity ($E$) $300 \text{ V m}^{-1}$ are parallel to each other in a region as shown in the figure. A particle of charge $+q$ enters at a velocity ($v$) $400 \text{ m s}^{-1}$ perpendicular to the fields and directed into the plane of the paper. The magnitude of the resultant force acting on the particle is</p>', '<p>A uniform magnet field of flux density ($B$) 1 T and a uniform electric field of field intensity ($E$) $300 \text{ V m}^{-1}$ are parallel to each other in a region as shown in the figure. A particle of charge $+q$ enters at a velocity ($v$) $400 \text{ m s}^{-1}$ perpendicular to the fields and directed into the plane of the paper. The magnitude of the resultant force acting on the particle is</p>', NULL, 'The electric force $F_e = qE = 300q$ acts parallel to the fields. The magnetic force $F_m = qvB = q(400)(1) = 400q$ acts perpendicular to both velocity and the B-field (using Fleming''s Left Hand Rule). Because $F_e$ and $F_m$ are strictly perpendicular to each other, the resultant total force $F_{\text{total}} = \sqrt{F_e^2 + F_m^2} = \sqrt{(300q)^2 + (400q)^2} = 500q$.', 'The electric force $F_e = qE = 300q$ acts parallel to the fields. The magnetic force $F_m = qvB = q(400)(1) = 400q$ acts perpendicular to both velocity and the B-field (using Fleming''s Left Hand Rule). Because $F_e$ and $F_m$ are strictly perpendicular to each other, the resultant total force $F_{\text{total}} = \sqrt{F_e^2 + F_m^2} = \sqrt{(300q)^2 + (400q)^2} = 500q$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
