INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b3739225-b176-5633-8818-69df5c3e65a8', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 35, '<p>A monochromatic ray of light falls on the surface of a glass sphere with incident angle 60° as shown in the figure. Refractive index of glass is $\sqrt{3}$. The total angle of deviation of the emerging ray from the sphere is</p>', '<p>A monochromatic ray of light falls on the surface of a glass sphere with incident angle 60° as shown in the figure. Refractive index of glass is $\sqrt{3}$. The total angle of deviation of the emerging ray from the sphere is</p>', NULL, 'By Snell''s law at the first surface, $\sin 60^{\circ} = \sqrt{3} \sin r \implies \frac{\sqrt{3}}{2} = \sqrt{3} \sin r \implies r = 30^{\circ}$. The deviation at the first interface is $60^{\circ} - 30^{\circ} = 30^{\circ}$. By geometric symmetry inside the sphere, the incident angle at the second interface is also $30^{\circ}$, so the ray emerges at $60^{\circ}$. The deviation at the second interface is $60^{\circ} - 30^{\circ} = 30^{\circ}$. Total deviation = $30^{\circ} + 30^{\circ} = 60^{\circ}$.', 'By Snell''s law at the first surface, $\sin 60^{\circ} = \sqrt{3} \sin r \implies \frac{\sqrt{3}}{2} = \sqrt{3} \sin r \implies r = 30^{\circ}$. The deviation at the first interface is $60^{\circ} - 30^{\circ} = 30^{\circ}$. By geometric symmetry inside the sphere, the incident angle at the second interface is also $30^{\circ}$, so the ray emerges at $60^{\circ}$. The deviation at the second interface is $60^{\circ} - 30^{\circ} = 30^{\circ}$. Total deviation = $30^{\circ} + 30^{\circ} = 60^{\circ}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
