INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('10ed831e-704c-5bc8-ae1b-e8b8ca086a04', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 44, '<p>A straight conducting wire PQ of length $l$ and mass $m$ has to be placed at rest on a frictionless insulating inclined plane, which makes an angle $\theta$ to the horizontal. A uniform magnetic field of flux density $B$ acts vertically upwards as shown in the figure. The magnitude and the direction of the current that should pass through the wire in order to keep the wire at rest is given by</p>', '<p>A straight conducting wire PQ of length $l$ and mass $m$ has to be placed at rest on a frictionless insulating inclined plane, which makes an angle $\theta$ to the horizontal. A uniform magnetic field of flux density $B$ acts vertically upwards as shown in the figure. The magnitude and the direction of the current that should pass through the wire in order to keep the wire at rest is given by</p>', NULL, 'For equilibrium, the component of gravity down the plane ($mg \sin \theta$) must be balanced by the component of the magnetic force up the plane. Magnetic force $F_m = I l B$ acts horizontally. Its component up the plane is $I l B \cos \theta$.<br>Thus, $I l B \cos \theta = mg \sin \theta \implies I = \frac{mg \tan \theta}{lB}$. Using Fleming''s left hand rule, the current must flow from Q to P.', 'For equilibrium, the component of gravity down the plane ($mg \sin \theta$) must be balanced by the component of the magnetic force up the plane. Magnetic force $F_m = I l B$ acts horizontally. Its component up the plane is $I l B \cos \theta$.<br>Thus, $I l B \cos \theta = mg \sin \theta \implies I = \frac{mg \tan \theta}{lB}$. Using Fleming''s left hand rule, the current must flow from Q to P.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
