INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('caf6a524-ec8e-531a-a51a-fd404a0bda06', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 45, '<p>A solid conducting sphere of radius $2R$ contains a cavity of radius $R$ inside it as shown in the figure. The sphere carries a net charge of $+q$. Another point charge of $+q$ is placed at the centre of the sphere. Which of the following graphs best represents the variation of the electric field intensity $E$ with the radial distance $r$ from the centre of the sphere?</p>', '<p>A solid conducting sphere of radius $2R$ contains a cavity of radius $R$ inside it as shown in the figure. The sphere carries a net charge of $+q$. Another point charge of $+q$ is placed at the centre of the sphere. Which of the following graphs best represents the variation of the electric field intensity $E$ with the radial distance $r$ from the centre of the sphere?</p>', NULL, 'Inside the cavity ($0 < r < R$), $E = \frac{k q}{r^2}$ (drops as $1/r^2$). Inside the bulk of the conductor ($R < r < 2R$), the electric field $E = 0$ strictly. Outside the sphere ($r > 2R$), the enclosed charge is $+q \text{ (point)} + q \text{ (conductor)} = +2q$, so $E = \frac{k(2q)}{r^2}$. The graph shows a $1/r^2$ decay, a zero flatline, and a jump at $2R$ to a subsequent $1/r^2$ decay.', 'Inside the cavity ($0 < r < R$), $E = \frac{k q}{r^2}$ (drops as $1/r^2$). Inside the bulk of the conductor ($R < r < 2R$), the electric field $E = 0$ strictly. Outside the sphere ($r > 2R$), the enclosed charge is $+q \text{ (point)} + q \text{ (conductor)} = +2q$, so $E = \frac{k(2q)}{r^2}$. The graph shows a $1/r^2$ decay, a zero flatline, and a jump at $2R$ to a subsequent $1/r^2$ decay.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
