INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('70ed2d97-e50f-5a23-a455-03014255ff0b', 'dd5332db-d083-59f8-b83e-1eb4c776d107', 50, '<p>An equilateral triangular conducting loop passes a region of uniform magnetic field of flux density $B$ at a uniform velocity $v$ as shown in the figure. The variation of the induced current ($I$) in the loop with time ($t$) is best represented by</p>', '<p>An equilateral triangular conducting loop passes a region of uniform magnetic field of flux density $B$ at a uniform velocity $v$ as shown in the figure. The variation of the induced current ($I$) in the loop with time ($t$) is best represented by</p>', NULL, 'As the triangular loop enters the uniform magnetic field apex first, the length of the conductor inside the field cutting flux increases linearly. Thus, the induced EMF ($E = Blv$) and resulting current increase linearly. Once the loop is entirely in the field, $\Delta \Phi / \Delta t = 0$, so $I = 0$. When exiting, the process is inverted, yielding a negative linear decrease.', 'As the triangular loop enters the uniform magnetic field apex first, the length of the conductor inside the field cutting flux increases linearly. Thus, the induced EMF ($E = Blv$) and resulting current increase linearly. Once the loop is entirely in the field, $\Delta \Phi / \Delta t = 0$, so $I = 0$. When exiting, the process is inverted, yielding a negative linear decrease.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
