INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2e54ac67-fba7-5387-b84e-f5130ad4bbfe', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 2, '<p>The magnitudes of two coplanar forces acting on a body are $11\text{ N}$ and $5\text{ N}$. Which one of the following values could not be equal to the magnitude of the resultant force?</p>', '<p>The magnitudes of two coplanar forces acting on a body are $11\text{ N}$ and $5\text{ N}$. Which one of the following values could not be equal to the magnitude of the resultant force?</p>', NULL, 'The magnitude of the resultant $R$ of two forces $F_1$ and $F_2$ must lie within the range $|F_1 - F_2| \le R \le F_1 + F_2$. For $11\text{ N}$ and $5\text{ N}$, the resultant must be between $6\text{ N}$ and $16\text{ N}$. Thus, $5\text{ N}$ is not possible.', 'The magnitude of the resultant $R$ of two forces $F_1$ and $F_2$ must lie within the range $|F_1 - F_2| \le R \le F_1 + F_2$. For $11\text{ N}$ and $5\text{ N}$, the resultant must be between $6\text{ N}$ and $16\text{ N}$. Thus, $5\text{ N}$ is not possible.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
