INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9bdc9b05-5459-52d3-b371-087fca7936ca', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 5, '<p>The back e.m.f. in an electric motor is maximum when the motor</p>', '<p>The back e.m.f. in an electric motor is maximum when the motor</p>', NULL, 'The back electromotive force ($E$) induced in the armature is directly proportional to its rotational angular speed ($\omega$). Thus, it reaches its maximum when the motor is at its maximum speed.', 'The back electromotive force ($E$) induced in the armature is directly proportional to its rotational angular speed ($\omega$). Thus, it reaches its maximum when the motor is at its maximum speed.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
