INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c136e96d-692f-5ff0-b623-b8beb84f14de', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 8, '<p>The surface temperature of the sun is $6000\text{ K}$ and it emits blackbody radiation at peak wavelength $500\text{ nm}$. For a blackbody with a surface temperature of $10 000\text{ K}$, what will be the value of peak wavelength of emitted radiation?</p>', '<p>The surface temperature of the sun is $6000\text{ K}$ and it emits blackbody radiation at peak wavelength $500\text{ nm}$. For a blackbody with a surface temperature of $10 000\text{ K}$, what will be the value of peak wavelength of emitted radiation?</p>', NULL, 'According to Wien''s Displacement Law, $\lambda_{max} T = \text{constant}$. Therefore, $\lambda_1 T_1 = \lambda_2 T_2$. Solving gives $\lambda_2 = \frac{500 \times 6000}{10000} = 300\text{ nm}$.', 'According to Wien''s Displacement Law, $\lambda_{max} T = \text{constant}$. Therefore, $\lambda_1 T_1 = \lambda_2 T_2$. Solving gives $\lambda_2 = \frac{500 \times 6000}{10000} = 300\text{ nm}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
