INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('951d0854-880f-5626-8323-4779ab376e32', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 9, '<p>The figure shows the path AB of a ball projected from point A. Neglect air resistance.<br><br>Consider the following statements.<br>(A) The velocity of the ball at the maximum height of the path is zero.<br>(B) The velocity of the ball at point B is equal to the velocity at point A.<br>(C) The kinetic energy of the ball at point B is equal to the kinetic energy at point A.<br><br>Of the above statements,</p>', '<p>The figure shows the path AB of a ball projected from point A. Neglect air resistance.<br><br>Consider the following statements.<br>(A) The velocity of the ball at the maximum height of the path is zero.<br>(B) The velocity of the ball at point B is equal to the velocity at point A.<br>(C) The kinetic energy of the ball at point B is equal to the kinetic energy at point A.<br><br>Of the above statements,</p>', NULL, 'At max height, the horizontal velocity component remains, so total velocity is not zero (A is false). Velocity is a vector, and at B its direction is different from A (B is false). Kinetic energy depends only on speed, which is the same at A and B, so (C) is true.', 'At max height, the horizontal velocity component remains, so total velocity is not zero (A is false). Velocity is a vector, and at B its direction is different from A (B is false). Kinetic energy depends only on speed, which is the same at A and B, so (C) is true.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
