INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ce4e68be-9347-53b6-a148-d698e6e3d41d', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 10, '<p>The Young''s modulus of the material of a wire depends on<br><br>(A) the initial length of the wire.<br>(B) the cross-sectional area of the wire.<br>(C) the nature of the material of the wire.<br><br>Of the above statements,</p>', '<p>The Young''s modulus of the material of a wire depends on<br><br>(A) the initial length of the wire.<br>(B) the cross-sectional area of the wire.<br>(C) the nature of the material of the wire.<br><br>Of the above statements,</p>', NULL, 'Young''s modulus is a material property. It depends exclusively on the nature of the material and is independent of the object''s dimensions like length and cross-sectional area.', 'Young''s modulus is a material property. It depends exclusively on the nature of the material and is independent of the object''s dimensions like length and cross-sectional area.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
