INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('46352643-895e-5a02-b103-8095d24ec502', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 11, '<p>A uniform electric field of intensity $200\text{ V m}^{-1}$ is applied in between a pair of parallel metallic plates. What should be the separation between the plates in order to produce a potential difference of $10\text{ V}$?</p>', '<p>A uniform electric field of intensity $200\text{ V m}^{-1}$ is applied in between a pair of parallel metallic plates. What should be the separation between the plates in order to produce a potential difference of $10\text{ V}$?</p>', NULL, 'Using the relation $E = \frac{V}{d}$, the separation $d = \frac{V}{E} = \frac{10}{200} = 0.05\text{ m} = 50\text{ mm}$.', 'Using the relation $E = \frac{V}{d}$, the separation $d = \frac{V}{E} = \frac{10}{200} = 0.05\text{ m} = 50\text{ mm}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
