INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('51dddec9-2456-5e7b-a778-895d11c10d74', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 13, '<p>Which of the following graphs best represents the variation of momentum ($p$) of a particle with its de Broglie wavelength ($\lambda$)</p>', '<p>Which of the following graphs best represents the variation of momentum ($p$) of a particle with its de Broglie wavelength ($\lambda$)</p>', NULL, 'According to the de Broglie relation, $p = \frac{h}{\lambda}$. This is an inverse relationship ($p \propto \frac{1}{\lambda}$), which forms a rectangular hyperbola (Graph 4).', 'According to the de Broglie relation, $p = \frac{h}{\lambda}$. This is an inverse relationship ($p \propto \frac{1}{\lambda}$), which forms a rectangular hyperbola (Graph 4).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
