INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cb97734a-ef0f-5d3c-8d05-d72e09f1455b', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 15, '<p>Consider the following statements made about absolute zero temperature.<br><br>(A) It is the temperature at which water freezes at atmospheric pressure.<br>(B) It is the temperature at which all gases become liquids.<br>(C) It is the temperature at which mean kinetic energy of an ideal gas becomes zero.<br><br>Of the above statements,</p>', '<p>Consider the following statements made about absolute zero temperature.<br><br>(A) It is the temperature at which water freezes at atmospheric pressure.<br>(B) It is the temperature at which all gases become liquids.<br>(C) It is the temperature at which mean kinetic energy of an ideal gas becomes zero.<br><br>Of the above statements,</p>', NULL, 'At absolute zero ($0\text{ K}$), the theoretical mean kinetic energy of an ideal gas molecules becomes exactly zero. Water freezes at $273.15\text{ K}$ (A is false), and real gases become liquid/solid before reaching $0\text{ K}$ (B is false).', 'At absolute zero ($0\text{ K}$), the theoretical mean kinetic energy of an ideal gas molecules becomes exactly zero. Water freezes at $273.15\text{ K}$ (A is false), and real gases become liquid/solid before reaching $0\text{ K}$ (B is false).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
