INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ba7ed1da-a3d4-5786-b215-4a7fa934677d', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 18, '<p>A body of mass $2\text{ kg}$ is initially at rest on a frictionless horizontal surface. Then a horizontal force $F$ varying with time $t$ as shown in the figure acts on the body during $6\text{ s}$. What is the final velocity of the body?</p>', '<p>A body of mass $2\text{ kg}$ is initially at rest on a frictionless horizontal surface. Then a horizontal force $F$ varying with time $t$ as shown in the figure acts on the body during $6\text{ s}$. What is the final velocity of the body?</p>', NULL, 'The impulse is the area under the F-t graph: $\text{Area} = (10 \times 4) + \frac{1}{2}(2)(10) = 50\text{ N s}$. Impulse equals change in momentum $\Delta p = mv$. Therefore, $50 = 2v \implies v = 25\text{ m s}^{-1}$.', 'The impulse is the area under the F-t graph: $\text{Area} = (10 \times 4) + \frac{1}{2}(2)(10) = 50\text{ N s}$. Impulse equals change in momentum $\Delta p = mv$. Therefore, $50 = 2v \implies v = 25\text{ m s}^{-1}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
