INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('82fbc8aa-e8de-5f13-a64c-0bf1d7934989', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 19, '<p>The figure shows the displacement ($s$) - time ($t$) graphs of two objects P and Q moving along a straight line.<br><br>Consider the following statements.<br>(A) Both objects have velocities in the same direction.<br>(B) Velocities of both objects increase with time.<br>(C) Both objects have the same velocity at the crossing point of the two graphs.<br><br>Of the above statements,</p>', '<p>The figure shows the displacement ($s$) - time ($t$) graphs of two objects P and Q moving along a straight line.<br><br>Consider the following statements.<br>(A) Both objects have velocities in the same direction.<br>(B) Velocities of both objects increase with time.<br>(C) Both objects have the same velocity at the crossing point of the two graphs.<br><br>Of the above statements,</p>', NULL, 'Both graphs have positive slopes, meaning both velocities are positive (A is true). The slope of Q decreases over time, so its velocity decreases (B is false). At the crossing point, their slopes are different, so their velocities are different (C is false).', 'Both graphs have positive slopes, meaning both velocities are positive (A is true). The slope of Q decreases over time, so its velocity decreases (B is false). At the crossing point, their slopes are different, so their velocities are different (C is false).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
