INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4edd8315-282f-5c87-8230-0716c0c65abb', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 21, '<p>Consider the following statements made regarding Tsunami waves.<br><br>(A) Wavelengths of waves in deep water are lower than that in shallow water.<br>(B) Speeds of waves are higher in deep water than that in shallow water.<br>(C) Amplitudes of the waves in deep water are higher than that in shallow water.<br><br>Of the above statements,</p>', '<p>Consider the following statements made regarding Tsunami waves.<br><br>(A) Wavelengths of waves in deep water are lower than that in shallow water.<br>(B) Speeds of waves are higher in deep water than that in shallow water.<br>(C) Amplitudes of the waves in deep water are higher than that in shallow water.<br><br>Of the above statements,</p>', NULL, 'Tsunami waves travel faster in deep water ($v = \sqrt{gh}$), so (B) is true. As they reach shallow water, they slow down, decreasing in wavelength and significantly increasing in amplitude. Thus, (A) and (C) are false.', 'Tsunami waves travel faster in deep water ($v = \sqrt{gh}$), so (B) is true. As they reach shallow water, they slow down, decreasing in wavelength and significantly increasing in amplitude. Thus, (A) and (C) are false.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
