INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('24b8cd5c-d640-5f67-a38a-c03bf538ac06', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 22, '<p>A triangular shaped portion QBR is removed from a uniform square sheet PORS and connected to form the composite sheet $PQB''RS$ as shown in the figure. The center of the gravity of the composite sheet is most likely to be at</p>', '<p>A triangular shaped portion QBR is removed from a uniform square sheet PORS and connected to form the composite sheet $PQB''RS$ as shown in the figure. The center of the gravity of the composite sheet is most likely to be at</p>', NULL, 'Moving the triangular mass from the right-inner side to the right-outer side shifts the center of mass to the right of the original geometric center C. Therefore, D is the most likely location.', 'Moving the triangular mass from the right-inner side to the right-outer side shifts the center of mass to the right of the original geometric center C. Therefore, D is the most likely location.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
