INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c8f31adb-b3fa-50f0-8ac9-6da20c849f9d', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 25, '<p>A ball released at point A travels on a frictionless track as shown in the figure. Then the ball just touches point B on the inner surface of the circular part of the track of radius $R$. What is the velocity of the ball at point B?</p>', '<p>A ball released at point A travels on a frictionless track as shown in the figure. Then the ball just touches point B on the inner surface of the circular part of the track of radius $R$. What is the velocity of the ball at point B?</p>', NULL, 'For the ball to "just touch" the top of the loop (point B), the normal force becomes zero. The centripetal force is provided entirely by gravity: $mg = \frac{mv^2}{R}$, which yields $v = \sqrt{gR}$.', 'For the ball to "just touch" the top of the loop (point B), the normal force becomes zero. The centripetal force is provided entirely by gravity: $mg = \frac{mv^2}{R}$, which yields $v = \sqrt{gR}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
