INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('92bdb15d-4d92-5e65-9380-bcae727bf164', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 26, '<p>Ten identical musical instruments placed along the circumference of a circle produce a sound intensity level of 50 dB at the center of the circle. How many identical musical instruments placed along the circumference are needed to produce a sound intensity level of 60 dB at the center?</p>', '<p>Ten identical musical instruments placed along the circumference of a circle produce a sound intensity level of 50 dB at the center of the circle. How many identical musical instruments placed along the circumference are needed to produce a sound intensity level of 60 dB at the center?</p>', NULL, 'A $10\text{ dB}$ increase corresponds to a 10-fold increase in sound intensity. If 10 instruments produce $50\text{ dB}$, producing $60\text{ dB}$ requires $10 \times 10 = 100$ instruments.', 'A $10\text{ dB}$ increase corresponds to a 10-fold increase in sound intensity. If 10 instruments produce $50\text{ dB}$, producing $60\text{ dB}$ requires $10 \times 10 = 100$ instruments.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
