INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2f8d7cce-e653-5360-ab6d-692bdb28408f', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 28, '<p>A person takes a picture of an aquatic plant in a container with thin glass walls using a convex lens. The container is filled with water. When the film, lens, and aquatic plant are positioned as shown in the figure, a clear image of the aquatic plant is recorded on the film.<br><br>(Refractive index of water = $\frac{4}{3}$)<br><br>What is the focal length of the convex lens?</p>', '<p>A person takes a picture of an aquatic plant in a container with thin glass walls using a convex lens. The container is filled with water. When the film, lens, and aquatic plant are positioned as shown in the figure, a clear image of the aquatic plant is recorded on the film.<br><br>(Refractive index of water = $\frac{4}{3}$)<br><br>What is the focal length of the convex lens?</p>', NULL, 'The apparent distance of the plant from the glass wall is $d'' = \frac{40}{4/3} = 30\text{ cm}$. The total object distance $u = - (30 + 10) = -40\text{ cm}$. Image distance $v = +10\text{ cm}$. Using lens formula $\frac{1}{f} = \frac{1}{v} - \frac{1}{u} = \frac{1}{10} + \frac{1}{40} = \frac{5}{40}$, so $f = 8.0\text{ cm}$.', 'The apparent distance of the plant from the glass wall is $d'' = \frac{40}{4/3} = 30\text{ cm}$. The total object distance $u = - (30 + 10) = -40\text{ cm}$. Image distance $v = +10\text{ cm}$. Using lens formula $\frac{1}{f} = \frac{1}{v} - \frac{1}{u} = \frac{1}{10} + \frac{1}{40} = \frac{5}{40}$, so $f = 8.0\text{ cm}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
