INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3b975cb6-91da-5923-9a18-361a59c8f48e', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 29, '<p>As shown in the figure, two point charges X and Y are fixed along a straight line. The charge of X is $+q$. When a negative point charge is placed at point P, it remains stationary. What is the charge of Y? Neglect all other forces acting on charges.</p>', '<p>As shown in the figure, two point charges X and Y are fixed along a straight line. The charge of X is $+q$. When a negative point charge is placed at point P, it remains stationary. What is the charge of Y? Neglect all other forces acting on charges.</p>', NULL, 'Based on the distances in the diagram (where $XP = \sqrt{2}x$ and $PY = x$), equating electric field magnitudes gives $\frac{k q}{(\sqrt{2}x)^2} = \frac{k q_y}{x^2}$. This simplifies to $q_y = \frac{q}{2}$. To keep the negative charge stationary between them, Y must also be a positive charge to pull oppositely to X. Thus, Y is $+q/2$.', 'Based on the distances in the diagram (where $XP = \sqrt{2}x$ and $PY = x$), equating electric field magnitudes gives $\frac{k q}{(\sqrt{2}x)^2} = \frac{k q_y}{x^2}$. This simplifies to $q_y = \frac{q}{2}$. To keep the negative charge stationary between them, Y must also be a positive charge to pull oppositely to X. Thus, Y is $+q/2$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
