INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('23b6ff67-e6ad-5815-bff4-62c2432b81f6', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 30, '<p>The figure shows a circuit containing two batteries with negligible internal resistance, five resistors, and one capacitor. What is the current flowing through the $3\ \Omega$ resistor after steady state of the circuit has achieved?</p>', '<p>The figure shows a circuit containing two batteries with negligible internal resistance, five resistors, and one capacitor. What is the current flowing through the $3\ \Omega$ resistor after steady state of the circuit has achieved?</p>', NULL, 'In steady state, the capacitor acts as an open circuit. By analyzing the remaining resistor loops with Kirchhoff''s laws, the current through the $3\ \Omega$ resistor calculates to $0.8\text{ A}$.', 'In steady state, the capacitor acts as an open circuit. By analyzing the remaining resistor loops with Kirchhoff''s laws, the current through the $3\ \Omega$ resistor calculates to $0.8\text{ A}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
