INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('26ef54af-1507-56f6-a235-5e25b4a315bb', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 31, '<p>A current carrying metallic wire with different cross-sections is shown in the figure. Consider the following statements.<br><br>(A) The current in the wire is same everywhere.<br>(B) The power dissipation of the wire is higher in the thin section than that in thick section.<br>(C) The drift velocity of electrons is higher in the thin section than that in thick section.<br><br>Of the above statements.</p>', '<p>A current carrying metallic wire with different cross-sections is shown in the figure. Consider the following statements.<br><br>(A) The current in the wire is same everywhere.<br>(B) The power dissipation of the wire is higher in the thin section than that in thick section.<br>(C) The drift velocity of electrons is higher in the thin section than that in thick section.<br><br>Of the above statements.</p>', NULL, 'Current is conserved so it''s equal throughout (A is true). Resistance is higher in the thin section, so power $I^2R$ is higher (B is true). Drift velocity $v = \frac{I}{neA}$ is inversely proportional to area, so it''s higher in the thin section (C is true).', 'Current is conserved so it''s equal throughout (A is true). Resistance is higher in the thin section, so power $I^2R$ is higher (B is true). Drift velocity $v = \frac{I}{neA}$ is inversely proportional to area, so it''s higher in the thin section (C is true).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
