INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ccbc00e0-4fbf-5035-9445-09e60af8dff2', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 32, '<p>Four metallic plates are placed at a separation $d$ from each other as shown in the figure. The overlapping area of each plate with the other is $A$. What is the equivalent capacitance of the system?</p>', '<p>Four metallic plates are placed at a separation $d$ from each other as shown in the figure. The overlapping area of each plate with the other is $A$. What is the equivalent capacitance of the system?</p>', NULL, 'The alternating connections of the four plates create 3 identical capacitors connected in parallel. Total capacitance is $C = 3 \times \left(\frac{\epsilon_0 A}{d}\right)$.', 'The alternating connections of the four plates create 3 identical capacitors connected in parallel. Total capacitance is $C = 3 \times \left(\frac{\epsilon_0 A}{d}\right)$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
