INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2eaeeb18-88f1-5153-9b15-e693d3fb37b9', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 34, '<p>Figure shows a siphon which is filled with a liquid. The respective heights are marked in the figure. What is the speed ($v$) of the emerging liquid from the siphon at C? Assume that the cross-sectional area of the liquid container is large compared to the cross-sectional area of the tube and the flow is steady and non-viscous.</p>', '<p>Figure shows a siphon which is filled with a liquid. The respective heights are marked in the figure. What is the speed ($v$) of the emerging liquid from the siphon at C? Assume that the cross-sectional area of the liquid container is large compared to the cross-sectional area of the tube and the flow is steady and non-viscous.</p>', NULL, 'Applying Bernoulli''s equation from the open surface of the tank to point C, the total hydrostatic head driving the flow is $h_2 + h_3$. Therefore, $v = \sqrt{2g(h_2 + h_3)}$.', 'Applying Bernoulli''s equation from the open surface of the tank to point C, the total hydrostatic head driving the flow is $h_2 + h_3$. Therefore, $v = \sqrt{2g(h_2 + h_3)}$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('24e032c9-cd22-4f20-aad3-8e69483474e5', '2eaeeb18-88f1-5153-9b15-e693d3fb37b9', '$v=\sqrt{2g(h_{1}+h_{2}+h_{3})}$', '$v=\sqrt{2g(h_{1}+h_{2}+h_{3})}$', NULL, 'sanitized', 'v1', 0, 1);
