INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('19929c13-a1e8-58f4-8833-ee64c11af122', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 38, '<p>Three identical, conducting spheres A, B and C are mounted on insulating supports and separated as shown in the figure. The sphere A is given a charge $+3q$ and C is given $-2q$ charge. The sphere B does not have a net charge. Then the sphere B is first touched to sphere C, next sphere B is touched to sphere A and finally spheres brought back to the initial positions. The remaining final charge in each sphere is given by,</p>', '<p>Three identical, conducting spheres A, B and C are mounted on insulating supports and separated as shown in the figure. The sphere A is given a charge $+3q$ and C is given $-2q$ charge. The sphere B does not have a net charge. Then the sphere B is first touched to sphere C, next sphere B is touched to sphere A and finally spheres brought back to the initial positions. The remaining final charge in each sphere is given by,</p>', NULL, 'B(0) touches C(-2q): they share equally, both get -q. B(-q) then touches A(+3q): total is +2q, they share equally, both get +q. Final charges: A is +q, B is +q, C is -q.', 'B(0) touches C(-2q): they share equally, both get -q. B(-q) then touches A(+3q): total is +2q, they share equally, both get +q. Final charges: A is +q, B is +q, C is -q.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
