INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f72322ce-ce86-57f0-90e2-eb337d5de777', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 41, '<p>Three circuit diagrams constructed using 12 resistors are shown in figures. What is the correct relationship of the currents $I_{a}$, $I_{b}$ and $I_{c}$ flowing in the circuits respectively?</p>', '<p>Three circuit diagrams constructed using 12 resistors are shown in figures. What is the correct relationship of the currents $I_{a}$, $I_{b}$ and $I_{c}$ flowing in the circuits respectively?</p>', NULL, 'Calculating the equivalent resistances of all three symmetrical combinations reveals that the total resistance across the source is identical ($5R/6$) in each topological configuration. Thus, $I_a = I_b = I_c$.', 'Calculating the equivalent resistances of all three symmetrical combinations reveals that the total resistance across the source is identical ($5R/6$) in each topological configuration. Thus, $I_a = I_b = I_c$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
