INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0ad5ee78-3e08-5e09-8d61-29cf0f8cb8cd', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 42, '<p>During a thermodynamic process from a to b, variation of mean kinetic energy $E$ of a given mass of an ideal gas with volume $V$ is shown in the figure. The corresponding variation of pressure $P$ with volume $V$ of the gas is best represented by</p>', '<p>During a thermodynamic process from a to b, variation of mean kinetic energy $E$ of a given mass of an ideal gas with volume $V$ is shown in the figure. The corresponding variation of pressure $P$ with volume $V$ of the gas is best represented by</p>', NULL, 'The linear graph shows kinetic energy $E \propto V$. Since $E \propto T$, we have $T \propto V$. According to the ideal gas law ($PV=nRT$), if $T \propto V$, then pressure $P$ must be constant. A constant pressure process is represented by a horizontal line (Graph 1).', 'The linear graph shows kinetic energy $E \propto V$. Since $E \propto T$, we have $T \propto V$. According to the ideal gas law ($PV=nRT$), if $T \propto V$, then pressure $P$ must be constant. A constant pressure process is represented by a horizontal line (Graph 1).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
