INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('57cc532b-4a84-5aff-a25a-b8c9f312a7a7', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 44, '<p>For which values of $R$ would the silicon transistor circuit shown be in cutoff region and active region, respectively?</p>', '<p>For which values of $R$ would the silicon transistor circuit shown be in cutoff region and active region, respectively?</p>', NULL, 'For cutoff, base voltage $V_B < 0.7\text{ V}$. $V_B = 10 \times \frac{R}{100+R}$, solving gives $R < 7.53\text{ k}\Omega$ (so $5\text{ k}\Omega$ works). For active, it needs enough current but not saturated. $R=7.5\text{ k}\Omega$ provides exactly adequate active region voltage biasing.', 'For cutoff, base voltage $V_B < 0.7\text{ V}$. $V_B = 10 \times \frac{R}{100+R}$, solving gives $R < 7.53\text{ k}\Omega$ (so $5\text{ k}\Omega$ works). For active, it needs enough current but not saturated. $R=7.5\text{ k}\Omega$ provides exactly adequate active region voltage biasing.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
