INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4b51875c-43fa-55b1-b38e-1c752a852106', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 47, '<p>Ambient air at $30^{\circ}\text{C}$ and relative humidity (RH) 90% is cooled to $10^{\circ}\text{C}$ and some of the moisture in air is removed by an air-conditioning plant. Then this air is heated to $20^{\circ}\text{C}$ and passed to a computer laboratory. If the values of saturated water vapour pressure at temperatures $10^{\circ}\text{C}$, $20^{\circ}\text{C}$ and $30^{\circ}\text{C}$ are given by $a, b$ and $c$ respectively, what is the ratio of moisture removed from the plant and the final relative humidity (RH) of the air at $20^{\circ}\text{C}$?</p>', '<p>Ambient air at $30^{\circ}\text{C}$ and relative humidity (RH) 90% is cooled to $10^{\circ}\text{C}$ and some of the moisture in air is removed by an air-conditioning plant. Then this air is heated to $20^{\circ}\text{C}$ and passed to a computer laboratory. If the values of saturated water vapour pressure at temperatures $10^{\circ}\text{C}$, $20^{\circ}\text{C}$ and $30^{\circ}\text{C}$ are given by $a, b$ and $c$ respectively, what is the ratio of moisture removed from the plant and the final relative humidity (RH) of the air at $20^{\circ}\text{C}$?</p>', NULL, 'Initial moisture corresponds to vapor pressure $0.9c$. After cooling to $10^{\circ}\text{C}$, it saturates at $a$, removing $(0.9c - a)$. Ratio removed = $\frac{0.9c - a}{0.9c}$. Upon heating to $20^{\circ}\text{C}$, actual vapor pressure remains $a$, while saturated is $b$. Final RH = $\frac{a}{b} \times 100\%$.', 'Initial moisture corresponds to vapor pressure $0.9c$. After cooling to $10^{\circ}\text{C}$, it saturates at $a$, removing $(0.9c - a)$. Ratio removed = $\frac{0.9c - a}{0.9c}$. Upon heating to $20^{\circ}\text{C}$, actual vapor pressure remains $a$, while saturated is $b$. Final RH = $\frac{a}{b} \times 100\%$.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4e28b3b8-f95e-4c9e-91eb-97955ef43d99', '4b51875c-43fa-55b1-b38e-1c752a852106', '$\frac{(0\cdot 9c-a)}{0\cdot 9c},\frac{a\times 100}{b}\%$', '$\frac{(0\cdot 9c-a)}{0\cdot 9c},\frac{a\times 100}{b}\%$', NULL, 'sanitized', 'v1', 0, 1);
