INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b9e5b89e-cf57-4219-aff9-c25bb327e5ff', '4b51875c-43fa-55b1-b38e-1c752a852106', '$\frac{(c-a)}{c},\frac{b\times 100}{c}\%$', '$\frac{(c-a)}{c},\frac{b\times 100}{c}\%$', NULL, 'sanitized', 'v1', 3, 0);
