INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('14bd30f0-3c1d-5eb4-9e14-2bbc36d1c7ab', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 49, '<p>Suppose a spacecraft moves from the earth to the moon. Which one of the following graphs best represents the variation of the magnitude of its net weight ($W$) with distance ($s$)? (Neglect the effect of other objects)</p>', '<p>Suppose a spacecraft moves from the earth to the moon. Which one of the following graphs best represents the variation of the magnitude of its net weight ($W$) with distance ($s$)? (Neglect the effect of other objects)</p>', NULL, 'Net weight $W = |F_{earth} - F_{moon}|$. It decreases as $1/r^2$ moving away from Earth, reaches exactly zero at the neutral point, and then increases under lunar gravity. Graph 5 uniquely shows the function dipping smoothly to zero and rising.', 'Net weight $W = |F_{earth} - F_{moon}|$. It decreases as $1/r^2$ moving away from Earth, reaches exactly zero at the neutral point, and then increases under lunar gravity. Graph 5 uniquely shows the function dipping smoothly to zero and rising.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
