INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ad328b63-aa27-5e13-82bd-2b46774d2885', 'deeeec01-a8c0-5f3d-8f6c-6c05b407e11b', 50, '<p>A long straight wire placed at the origin O carries a constant current directed out of the paper along the Z-axis. Figure shows a semicircle of radius R drawn on the X-Y plane centering the wire. Which one of the following graphs best represents the variation of the x-component of the magnetic flux density $(B_{x})$ along the semicircular path with x?</p>', '<p>A long straight wire placed at the origin O carries a constant current directed out of the paper along the Z-axis. Figure shows a semicircle of radius R drawn on the X-Y plane centering the wire. Which one of the following graphs best represents the variation of the x-component of the magnetic flux density $(B_{x})$ along the semicircular path with x?</p>', NULL, 'By Ampere''s right-hand rule, the B-field forms counterclockwise concentric circles. On the semicircle $y>0$, the B vector points generally leftward (negative $x$-direction). $B_x = -B\sin\theta = -B(y/R)$. Since $B$ is constant on the semicircle, $B_x$ is proportional to $-y$. As $x$ goes $-R \to 0 \to R$, $y$ goes $0 \to R \to 0$. So $B_x$ goes $0 \to -\text{max} \to 0$, matching Graph 2.', 'By Ampere''s right-hand rule, the B-field forms counterclockwise concentric circles. On the semicircle $y>0$, the B vector points generally leftward (negative $x$-direction). $B_x = -B\sin\theta = -B(y/R)$. Since $B$ is constant on the semicircle, $B_x$ is proportional to $-y$. As $x$ goes $-R \to 0 \to R$, $y$ goes $0 \to R \to 0$. So $B_x$ goes $0 \to -\text{max} \to 0$, matching Graph 2.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
