INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('96bf3a31-4c5d-5c0a-9de2-e0b229787ee3', 'df96637c-b9a3-59a5-a35c-414951e72b14', 7, '<p>භූ කම්පන තරංග සම්බන්ධයෙන් කර ඇති පහත ප්‍රකාශ වලින් අසත්‍ය වන්නේ කුමක්ද?</p>', '<p>භූ කම්පන තරංග සම්බන්ධයෙන් කර ඇති පහත ප්‍රකාශ වලින් අසත්‍ය වන්නේ කුමක්ද?</p>', NULL, 'භූ කම්පන තරංග අතරින් ප්‍රාථමික තරංග (P-waves) ඝන, ද්‍රව සහ වායු යන ඕනෑම මාධ්‍යයක් හරහා ගමන් කළ හැකි මුත්, ද්විතියික තරංග හෙවත් S-තරංග වලට ගමන් කළ හැක්කේ ඝන මාධ්‍ය හරහා පමණි. එබැවින් S-තරංග වලට ද්‍රව හරහා ගමන් කළ හැකිය යන ප්‍රකාශය අසත්‍ය වේ.', 'භූ කම්පන තරංග අතරින් ප්‍රාථමික තරංග (P-waves) ඝන, ද්‍රව සහ වායු යන ඕනෑම මාධ්‍යයක් හරහා ගමන් කළ හැකි මුත්, ද්විතියික තරංග හෙවත් S-තරංග වලට ගමන් කළ හැක්කේ ඝන මාධ්‍ය හරහා පමණි. එබැවින් S-තරංග වලට ද්‍රව හරහා ගමන් කළ හැකිය යන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7fc8e4de-3d02-43bc-8747-0638566daa0f', '96bf3a31-4c5d-5c0a-9de2-e0b229787ee3', 'සියලුම භූ කම්පන තරංග යාන්ත්‍රික තරංග වන අතර ඒවා ප්‍රගමනය වීම සඳහා මාධ්‍යයක් අවශ්‍ය වේ.', 'සියලුම භූ කම්පන තරංග යාන්ත්‍රික තරංග වන අතර ඒවා ප්‍රගමනය වීම සඳහා මාධ්‍යයක් අවශ්‍ය වේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3da3f181-6cff-4452-b83c-9a5f1c957e6d', '96bf3a31-4c5d-5c0a-9de2-e0b229787ee3', 'ප්‍රාථමික (P) තරංග අන්වායාම තරංග වන අතර ද්විතීයික (S) තරංග තීර්යක් තරංග වේ.', 'ප්‍රාථමික (P) තරංග අන්වායාම තරංග වන අතර ද්විතීයික (S) තරංග තීර්යක් තරංග වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('216eae58-5772-4bfb-bf25-d235d3da5b11', '96bf3a31-4c5d-5c0a-9de2-e0b229787ee3', 'P - තරංගවල වේගයට වඩා S - තරංගවල වේගය අඩුය.', 'P - තරංගවල වේගයට වඩා S - තරංගවල වේගය අඩුය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3d24f2d1-bbd0-47b2-a411-b09cc2f9ab04', '96bf3a31-4c5d-5c0a-9de2-e0b229787ee3', 'S - තරංග වලට ද්‍රව සහ ඝන යන මාධ්‍ය දෙක තුළින්ම ගමන් කළ හැකිය.', 'S - තරංග වලට ද්‍රව සහ ඝන යන මාධ්‍ය දෙක තුළින්ම ගමන් කළ හැකිය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('077b3e81-e192-4be7-a088-2e2e5b5eddbc', '96bf3a31-4c5d-5c0a-9de2-e0b229787ee3', 'P - තරංග වලට ද්‍රව සහ ඝන යන මාධ්‍ය දෙක තුළින්ම ගමන් කළ හැකිය.', 'P - තරංග වලට ද්‍රව සහ ඝන යන මාධ්‍ය දෙක තුළින්ම ගමන් කළ හැකිය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7446ba24-8a53-52ce-a468-9218d1ab1ee5', 'df96637c-b9a3-59a5-a35c-414951e72b14', 8, '<p>රූපයේ පෙන්වා ඇති පරිදි XY පටු ඒක වර්ණ ආලෝක කදම්බයක් L අභිසරණ කාචය මතට පතනය වේ. කාචයෙන් වර්තනය වූ පසු කදම්බය S තිරයේ වැදී ආලෝක ලපයක් සාදයි. ආලෝක ලපය පිහිටන ස්ථානය කුමක් විය හැකි ද?</p>', '<p>රූපයේ පෙන්වා ඇති පරිදි XY පටු ඒක වර්ණ ආලෝක කදම්බයක් L අභිසරණ කාචය මතට පතනය වේ. කාචයෙන් වර්තනය වූ පසු කදම්බය S තිරයේ වැදී ආලෝක ලපයක් සාදයි. ආලෝක ලපය පිහිටන ස්ථානය කුමක් විය හැකි ද?</p>', NULL, 'කාචය මත පතිත වන කිරණයට සමාන්තරව, කාචයේ ප්‍රකාශ කේන්ද්‍රය හරහා යන කිරණයක් සැලකූ විට එය නොනැමී ගමන් කර නාභීය තලයේ කිසියම් ලක්ෂ්‍යයක් හමුවේ. පතිත කිරණය ද වර්තනයෙන් පසු නාභීය තලය මත දී එම ලක්ෂ්‍යයම හරහා ගමන් කළ යුතුය. රූපයේ ජ්‍යාමිතියට අනුව, XY ට සමාන්තරව ප්‍රකාශ කේන්ද්‍රය හරහා අඳින රේඛාව තිරය (නාභීය තලය) මත C ලක්ෂ්‍යය හමුවන බව පෙනේ. එබැවින් වර්තනය වූ කිරණය C හරහා ගමන් කරයි.', 'කාචය මත පතිත වන කිරණයට සමාන්තරව, කාචයේ ප්‍රකාශ කේන්ද්‍රය හරහා යන කිරණයක් සැලකූ විට එය නොනැමී ගමන් කර නාභීය තලයේ කිසියම් ලක්ෂ්‍යයක් හමුවේ. පතිත කිරණය ද වර්තනයෙන් පසු නාභීය තලය මත දී එම ලක්ෂ්‍යයම හරහා ගමන් කළ යුතුය. රූපයේ ජ්‍යාමිතියට අනුව, XY ට සමාන්තරව ප්‍රකාශ කේන්ද්‍රය හරහා අඳින රේඛාව තිරය (නාභීය තලය) මත C ලක්ෂ්‍යය හමුවන බව පෙනේ. එබැවින් වර්තනය වූ කිරණය C හරහා ගමන් කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode 