INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3cd6269a-6085-504e-bd1b-9365957ac9ea', 'df96637c-b9a3-59a5-a35c-414951e72b14', 15, '<p>පහත ප්‍රකාශ අතුරෙන් අසත්‍ය වන්නේ කුමක්ද?</p>', '<p>පහත ප්‍රකාශ අතුරෙන් අසත්‍ය වන්නේ කුමක්ද?</p>', NULL, 'කාරකාත්මක වර්ධකයක් (Op-amp) වෝල්ටීයතා සංසන්දකයක් (Voltage comparator) ලෙස භාවිත කරනුයේ එහි විවෘත පුඩු (Open-loop) අවස්ථාවේදී ය. එනම් එහි ප්‍රතිපෝෂණයක් (feedback) භාවිත නොකෙරේ. එබැවින් සංවෘත පුඩු අවස්ථාව භාවිත කරයි යන ප්‍රකාශය අසත්‍ය වේ.', 'කාරකාත්මක වර්ධකයක් (Op-amp) වෝල්ටීයතා සංසන්දකයක් (Voltage comparator) ලෙස භාවිත කරනුයේ එහි විවෘත පුඩු (Open-loop) අවස්ථාවේදී ය. එනම් එහි ප්‍රතිපෝෂණයක් (feedback) භාවිත නොකෙරේ. එබැවින් සංවෘත පුඩු අවස්ථාව භාවිත කරයි යන ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9512768a-eaaf-486e-9603-710c296ab22b', '3cd6269a-6085-504e-bd1b-9365957ac9ea', 'නිසග අර්ධ සන්නායකයක උෂ්ණත්වය වැඩි වන විට එහි විද්‍යුත් සන්නායකතාව වැඩිවේ.', 'නිසග අර්ධ සන්නායකයක උෂ්ණත්වය වැඩි වන විට එහි විද්‍යුත් සන්නායකතාව වැඩිවේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cd66248b-6c57-47ac-8f03-6badaebf763f', '3cd6269a-6085-504e-bd1b-9365957ac9ea', 'පුර්ණ - තරංග ඍජුකාරකයක් මගින් සයිනාකාර ප්‍රදානයකින් නියත සරල වෝල්ටීයතා (d.c.) ප්‍රතිදානයක් ලබා ගත නොහැක.', 'පුර්ණ - තරංග ඍජුකාරකයක් මගින් සයිනාකාර ප්‍රදානයකින් නියත සරල වෝල්ටීයතා (d.c.) ප්‍රතිදානයක් ලබා ගත නොහැක.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('17aa7bdf-297e-47a5-a6a1-45f08a9ddf11', '3cd6269a-6085-504e-bd1b-9365957ac9ea', 'ද්විධ්‍රැව ට්‍රාන්සිස්ටරයක සංග්‍රාහකයේ මාත්‍රණයට වඩා විමෝචකය අධික ලෙස මාත්‍රණය කර ඇත.', 'ද්විධ්‍රැව ට්‍රාන්සිස්ටරයක සංග්‍රාහකයේ මාත්‍රණයට වඩා විමෝචකය අධික ලෙස මාත්‍රණය කර ඇත.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('361024b2-af79-4952-b802-eda36ea2d0c3', '3cd6269a-6085-504e-bd1b-9365957ac9ea', 'සන්ධීය ක්ෂේත්‍ර ආචරණ ට්‍රාන්සිස්ටරයක (JFET) සොරොව් ධාරාව $(I_{D})$ උපරිම වන්නේ ද්වාර - ප්‍රභව වෝල්ටීයතාව ශූන්‍ය $(V_{GS}=0)$ වන විටය.', 'සන්ධීය ක්ෂේත්‍ර ආචරණ ට්‍රාන්සිස්ටරයක (JFET) සොරොව් ධාරාව $(I_{D})$ උපරිම වන්නේ ද්වාර - ප්‍රභව වෝල්ටීයතාව ශූන්‍ය $(V_{GS}=0)$ වන විටය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('914b1556-9d43-4d5c-90d2-0c7eae6d8cac', '3cd6269a-6085-504e-bd1b-9365957ac9ea', 'කාරකාත්මක වර්ධකයක්, වෝල්ටීයතා සංසන්දකයක් ලෙස යොදා ගැනීමේ දී එහි සංවෘත පුඩු අවස්ථාව භාවිත කරයි.', 'කාරකාත්මක වර්ධකයක්, වෝල්ටීයතා සංසන්දකයක් ලෙස යොදා ගැනීමේ දී එහි සංවෘත පුඩු අවස්ථාව භාවිත කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('58043730-0f75-5de0-80d1-87d2afb38ec8', 'df96637c-b9a3-59a5-a35c-414951e72b14', 16, '<p>ස්කන්ධය $m$ වූ අංශුවක් සරල අනුවර්තී චලිතයක යෙදේ. අංශුවේ උපරිම ප්‍රවේගය සහ උපරිම ත්වරණය පිළිවෙළින් $V$ සහ $a$ නම්, අංශුවේ කෝණික සංඛ්‍යාතය ($\omega$) දෙනු ලබන්නේ,</p>', '<p>ස්කන්ධය $m$ වූ අංශුවක් සරල අනුවර්තී චලිතයක යෙදේ. අංශුවේ උපරිම ප්‍රවේගය සහ උපරිම ත්වරණය පිළිවෙළින් $V$ සහ $a$ නම්, අංශුවේ කෝණික සංඛ්‍යාතය ($\omega$) දෙනු ලබන්නේ,</p>', NULL, 'සරල අනුවර්තී චලිතයක යෙදෙන අංශුවක විස්තාරය $A$ ද කෝණික සංඛ්‍යාතය $\omega$ ද නම්,<br>උපරිම ප්‍රවේගය $V = A\omega$<br>උපරිම ත්වරණය $a = A\omega^2$<br>මෙම සමීකරණ දෙක බෙදීමෙන්, $\frac{a}{V} = \frac{A\omega^2}{A\omega} = \omega$<br>එබැවින්, කෝණික සංඛ්‍යාතය $\omega = \frac{a}{V}$ වේ.', 'සරල අනුවර්තී චලිතයක යෙදෙන අංශුවක විස්තාරය $A$ ද කෝණික සංඛ්‍යාතය $\omega$ ද නම්,<br>උපරිම ප්‍රවේගය $V = A\omega$<br>උපරිම ත්වරණය $a = A\omega^2$<br>මෙම සමීකරණ දෙක බෙදීමෙන්, $\frac{a}{V} = \frac{A\omega^2}{A\omega} = \omega$<br>එබැවින්, කෝණික සංඛ්‍යාතය $\omega = \frac{a}{V}$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
