INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c4ecc5c5-a719-437c-958c-08faac41930d', 'b496ec7d-881c-5d30-88dc-1b83f114f63d', 'මිනිත්තු 25', 'මිනිත්තු 25', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ae43f2f8-d9e7-5700-b783-e9d775c4cae7', 'df96637c-b9a3-59a5-a35c-414951e72b14', 35, '<p>නොගිණිය හැකි තාප ධාරිතාවක් සහිත බඳුනක $35^{\circ}C$ හි පවතින ජලය $1~kg$ තුළ සම්පූර්ණයෙන් දිය කළ හැකි $-5^{\circ}C$ පවතින අයිස්වල උපරිම ස්කන්ධය කොපමණ ද?<br><br>අයිස් සහ ජලයේ විශිෂ්ට තාප ධාරිතා පිළිවෙළින් $2.0 \times 10^{3}~J~kg^{-1}~^{\circ}C^{-1}$ සහ $4.0 \times 10^{3}~J~kg^{-1}~^{\circ}C^{-1}$ ලෙසද අයිස් හි විලයනයේ විශිෂ්ට ගුප්ත තාපය $3.4 \times 10^{5}~J~kg^{-1}$ ලෙසද සලකන්න. පරිසරය සමඟ තාපය හුවමාරු නොවූයේ යැයි උපකල්පනය කරන්න.</p>', '<p>නොගිණිය හැකි තාප ධාරිතාවක් සහිත බඳුනක $35^{\circ}C$ හි පවතින ජලය $1~kg$ තුළ සම්පූර්ණයෙන් දිය කළ හැකි $-5^{\circ}C$ පවතින අයිස්වල උපරිම ස්කන්ධය කොපමණ ද?<br><br>අයිස් සහ ජලයේ විශිෂ්ට තාප ධාරිතා පිළිවෙළින් $2.0 \times 10^{3}~J~kg^{-1}~^{\circ}C^{-1}$ සහ $4.0 \times 10^{3}~J~kg^{-1}~^{\circ}C^{-1}$ ලෙසද අයිස් හි විලයනයේ විශිෂ්ට ගුප්ත තාපය $3.4 \times 10^{5}~J~kg^{-1}$ ලෙසද සලකන්න. පරිසරය සමඟ තාපය හුවමාරු නොවූයේ යැයි උපකල්පනය කරන්න.</p>', NULL, 'උපරිම අයිස් ස්කන්ධය දිය වූ පසු පද්ධතියේ අවසාන උෂ්ණත්වය $0^{\circ}C$ විය යුතුය.<br>ජලය මගින් පිටකල තාපය = $m_w c_w \Delta\theta = 1~kg \times 4.0 \times 10^3~J~kg^{-1}~^{\circ}C^{-1} \times (35 - 0)^{\circ}C = 140,000~J$<br>අයිස් ලබාගත් තාපය ($m$ යනු අයිස් ස්කන්ධයයි) = $-5^{\circ}C$ සිට $0^{\circ}C$ දක්වා රත්වීමට තාපය + $0^{\circ}C$ දී දියවීමට තාපය<br>$= m \times (2.0 \times 10^3) \times (0 - (-5)) + m \times (3.4 \times 10^5) = 10,000m + 340,000m = 350,000m$<br><br>තාප හුවමාරුව අනුව:<br>$350,000m = 140,000 \Rightarrow m = \frac{140,000}{350,000} = 0.4~kg = 400~g$ වේ.', 'උපරිම අයිස් ස්කන්ධය දිය වූ පසු පද්ධතියේ අවසාන උෂ්ණත්වය $0^{\circ}C$ විය යුතුය.<br>ජලය මගින් පිටකල තාපය = $m_w c_w \Delta\theta = 1~kg \times 4.0 \times 10^3~J~kg^{-1}~^{\circ}C^{-1} \times (35 - 0)^{\circ}C = 140,000~J$<br>අයිස් ලබාගත් තාපය ($m$ යනු අයිස් ස්කන්ධයයි) = $-5^{\circ}C$ සිට $0^{\circ}C$ දක්වා රත්වීමට තාපය + $0^{\circ}C$ දී දියවීමට තාපය<br>$= m \times (2.0 \times 10^3) \times (0 - (-5)) + m \times (3.4 \times 10^5) = 10,000m + 340,000m = 350,000m$<br><br>තාප හුවමාරුව අනුව:<br>$350,000m = 140,000 \Rightarrow m = \frac{140,000}{350,000} = 0.4~kg = 400~g$ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
