INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0c9ebbf5-48d7-46c2-8e60-8e4553afd573', '4076747d-3e07-574b-964f-44802f1baca3', '$R > 3~\Omega$', '$R > 3~\Omega$', NULL, 'sanitized', 'v1', 2, 0);
