INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d9b1539a-55e6-49e6-9432-36788d8da615', 'e5eaa0b7-eb1d-5e72-a738-1dd1d6e85d62', 'කුමාරසිංහ, ජයකොඩි, සරච්චන්ද්‍ර, නන්දිමිත්‍ර', 'කුමාරසිංහ, ජයකොඩි, සරච්චන්ද්‍ර, නන්දිමිත්‍ර', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('005c05d5-57e0-4f42-9a25-b61ac6abf845', 'e5eaa0b7-eb1d-5e72-a738-1dd1d6e85d62', 'කරුණාසේන, දයාසේන, කරුණාරත්න, සුනේත්‍රා', 'කරුණාසේන, දයාසේන, කරුණාරත්න, සුනේත්‍රා', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('770edbc7-5b35-5c6f-86c9-ed45c9411636', 'e03e75ba-c88e-5244-8d46-3a35a1b366dd', 11, '<p>අනුක්ත නාම පද පමණක් යෙදී ඇති වරණය තෝරන්න.</p>', '<p>අනුක්ත නාම පද පමණක් යෙදී ඇති වරණය තෝරන්න.</p>', NULL, 'අනුක්ත නාම පද යනු වාක්‍යයක කර්මය ආදිය ලෙස යෙදෙන පද වේ. ''ඌරකු, වැඳිරියක, අංගනාවන්, අහිංසකයකු'' යන සියල්ල අනුක්ත පද වේ. අනෙක් වරණවල උක්ත පද (උදා: නාගරිකයෙක්, වැද්දෙක්, ලේඛිකාවක්) අඩංගු ය.', 'අනුක්ත නාම පද යනු වාක්‍යයක කර්මය ආදිය ලෙස යෙදෙන පද වේ. ''ඌරකු, වැඳිරියක, අංගනාවන්, අහිංසකයකු'' යන සියල්ල අනුක්ත පද වේ. අනෙක් වරණවල උක්ත පද (උදා: නාගරිකයෙක්, වැද්දෙක්, ලේඛිකාවක්) අඩංගු ය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
