INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('02c2fd4d-055a-529f-8fea-354ef851d9d6', 'e03e75ba-c88e-5244-8d46-3a35a1b366dd', 26, '<p>අංක 26, 27 ප්‍රශ්න යටතේ දක්වා ඇති අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.<br><br>යමක් අවිනිශ්චිත ස්වරූපයෙන් පැවතීම</p>', '<p>අංක 26, 27 ප්‍රශ්න යටතේ දක්වා ඇති අදහසට වඩාත් ම ගැළපෙන ප්‍රස්තාව පිරුළ අන්තර්ගත වරණය තෝරන්න.<br><br>යමක් අවිනිශ්චිත ස්වරූපයෙන් පැවතීම</p>', NULL, '''මඩේ හිටවපු ඉන්න වගේ'' යන පිරුළෙන් අදහස් වන්නේ ස්ථිරත්වයක් නොමැතිව, එහාට මෙහාට වැනෙන අවිනිශ්චිත ස්වරූපයකි.', '''මඩේ හිටවපු ඉන්න වගේ'' යන පිරුළෙන් අදහස් වන්නේ ස්ථිරත්වයක් නොමැතිව, එහාට මෙහාට වැනෙන අවිනිශ්චිත ස්වරූපයකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('27f96306-2642-4b1b-ade9-88c11b2e7bdf', '02c2fd4d-055a-529f-8fea-354ef851d9d6', 'එළිපත්ත උඩ ඉන්න බළලා වගේ.', 'එළිපත්ත උඩ ඉන්න බළලා වගේ.', NULL, 'sanitized', 'v1', 0, 1);
