INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('992173eb-e8a7-4c0c-8764-1a70459ac1ed', '02c2fd4d-055a-529f-8fea-354ef851d9d6', 'ගහෙන් වැටුණු මිනිහට ගොනා ඇන්න වගේ.', 'ගහෙන් වැටුණු මිනිහට ගොනා ඇන්න වගේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e8254d42-60a5-5ced-a754-d4338b364ffc', 'e03e75ba-c88e-5244-8d46-3a35a1b366dd', 27, '<p>පිටින් පෙනෙන දේට වඩා සම්පූර්ණයෙන් වෙනස් දෙයක් අභ්‍යන්තරයේ වීම</p>', '<p>පිටින් පෙනෙන දේට වඩා සම්පූර්ණයෙන් වෙනස් දෙයක් අභ්‍යන්තරයේ වීම</p>', NULL, '''හක්කෙ බුදුරැස් බොක්කෙ දඩමස්'' යනු පිටතින් ඉතා ශුද්ධවන්තයෙකු සේ පෙනී සිටිමින් ඇතුළතින් පාපතර අදහස් දැරීමයි.', '''හක්කෙ බුදුරැස් බොක්කෙ දඩමස්'' යනු පිටතින් ඉතා ශුද්ධවන්තයෙකු සේ පෙනී සිටිමින් ඇතුළතින් පාපතර අදහස් දැරීමයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('79352b27-48d9-4860-bdfa-4e859e3c9195', 'e8254d42-60a5-5ced-a754-d4338b364ffc', 'උදේ පටන් වතුර ඇදල හැන්දෑවට කළේ බින්දා වගේ', 'උදේ පටන් වතුර ඇදල හැන්දෑවට කළේ බින්දා වගේ', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2dd12040-928b-4028-98e2-8dae82e5585a', 'e8254d42-60a5-5ced-a754-d4338b364ffc', 'ගලෙන් පට්ටයක් ගන්නා වගේ.', 'ගලෙන් පට්ටයක් ගන්නා වගේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ae0e9b3e-60c4-4511-aa93-704507cb1bef', 'e8254d42-60a5-5ced-a754-d4338b364ffc', 'කොහොඹ ගහට කරවිල වැල ගියා වගේ.', 'කොහොඹ ගහට කරවිල වැල ගියා වගේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5b01bee1-e641-4b6f-b00f-3640bb80273a', 'e8254d42-60a5-5ced-a754-d4338b364ffc', 'හක්කෙ බුදුරැස් බොක්කෙ දඩමස් තිබෙන්නා වගේ.', 'හක්කෙ බුදුරැස් බොක්කෙ දඩමස් තිබෙන්නා වගේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('886581fc-f8f0-5f9a-90da-9759407b0f05', 'e03e75ba-c88e-5244-8d46-3a35a1b366dd', 28, '<p>ආගම සන්ධියට හා ස්වරාදේශ සන්ධියට අදාළ නිදසුන් පිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', '<p>ආගම සන්ධියට හා ස්වරාදේශ සන්ධියට අදාළ නිදසුන් පිළිවෙළින් දැක්වෙන වරණය තෝරන්න.</p>', NULL, '''නිරවුල්'' (නි + අවුල් -> නි + ර් + අවුල්) යනු ආගම සන්ධියකි. ''මහෝපකාර'' (මහා + උපකාර -> මහා + ඕ + පකාර) යනු ස්වරාදේශ සන්ධියකි.', '''නිරවුල්'' (නි + අවුල් -> නි + ර් + අවුල්) යනු ආගම සන්ධියකි. ''මහෝපකාර'' (මහා + උපකාර -> මහා + ඕ + පකාර) යනු ස්වරාදේශ සන්ධියකි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
