INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('dd468713-358d-5e26-bbeb-f9319f9212eb', 'e03e75ba-c88e-5244-8d46-3a35a1b366dd', 29, '<p>අංක 29, 30 යටතේ දක්වා ඇති ප්‍රශ්න වල ව්‍යාකරණානුකූල ව නිවැරදි වාක්‍යය තෝරන්න.</p>', '<p>අංක 29, 30 යටතේ දක්වා ඇති ප්‍රශ්න වල ව්‍යාකරණානුකූල ව නිවැරදි වාක්‍යය තෝරන්න.</p>', NULL, '''වේවා'' යනු ආශිර්වාද ක්‍රියාවක් වන අතර එය ඒකවචන, බහුවචන දෙකටම එක සේ යෙදිය හැක. අනෙක් වාක්‍යවල උක්ත ආඛ්‍යාත දෝෂ පවතී.', '''වේවා'' යනු ආශිර්වාද ක්‍රියාවක් වන අතර එය ඒකවචන, බහුවචන දෙකටම එක සේ යෙදිය හැක. අනෙක් වාක්‍යවල උක්ත ආඛ්‍යාත දෝෂ පවතී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('16b64b94-3d0f-4071-9581-2d773bcb8982', 'dd468713-358d-5e26-bbeb-f9319f9212eb', 'දරුවනි, වඳුරන් සේ කෑම සඟවා ගෙන නො කව.', 'දරුවනි, වඳුරන් සේ කෑම සඟවා ගෙන නො කව.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c5982061-8650-4b5a-bdd0-ac3df3ecfb96', 'dd468713-358d-5e26-bbeb-f9319f9212eb', 'අසුරයෝ හා සුරයන් ගැටෙති.', 'අසුරයෝ හා සුරයන් ගැටෙති.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e813b51d-9992-417f-a7c6-99ba1239288a', 'dd468713-358d-5e26-bbeb-f9319f9212eb', 'ලේඛකයා කථිකයෙක් ද විචාරකයෙක් ද වෙති.', 'ලේඛකයා කථිකයෙක් ද විචාරකයෙක් ද වෙති.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3aace249-f764-445c-8099-2327349476cb', 'dd468713-358d-5e26-bbeb-f9319f9212eb', 'රටට, ජනතාවට හිතැති යහපත් පාලකයෙක් පහළ වේවා!', 'රටට, ජනතාවට හිතැති යහපත් පාලකයෙක් පහළ වේවා!', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('798fcfd2-db08-5527-9dca-887d74781888', 'e03e75ba-c88e-5244-8d46-3a35a1b366dd', 30, '<p>ව්‍යාකරණානුකූල ව නිවැරදි වාක්‍යය තෝරන්න.</p>', '<p>ව්‍යාකරණානුකූල ව නිවැරදි වාක්‍යය තෝරන්න.</p>', NULL, '''විශේෂඥයෝ'' යන බහුවචන උක්ත පදයට අනුරූපව ''වෙති'' යන බහුවචන ආඛ්‍යාතය නිවැරදිව යෙදී ඇත.', '''විශේෂඥයෝ'' යන බහුවචන උක්ත පදයට අනුරූපව ''වෙති'' යන බහුවචන ආඛ්‍යාතය නිවැරදිව යෙදී ඇත.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
