INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5f4c06e4-d8cf-4dce-aaef-4502aa681dc7', '798fcfd2-db08-5527-9dca-887d74781888', 'කායික රෝග විශේෂඥයෝ මානසික රෝග විශේෂඥයෝ නො වෙති.', 'කායික රෝග විශේෂඥයෝ මානසික රෝග විශේෂඥයෝ නො වෙති.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a6811d96-ac17-4571-8ede-4cd519cda029', '798fcfd2-db08-5527-9dca-887d74781888', 'මැතිවරණයේ දී ඡන්දදායකයෝ නිවැරදි තීරණයක් ගනීවි.', 'මැතිවරණයේ දී ඡන්දදායකයෝ නිවැරදි තීරණයක් ගනීවි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f1c3da12-4761-4606-983c-5fea4fe5da40', '798fcfd2-db08-5527-9dca-887d74781888', 'ඇතැම් මිනිස්සු වංචනික ක්‍රියාවල නිරත වන්නේ ඇයි?', 'ඇතැම් මිනිස්සු වංචනික ක්‍රියාවල නිරත වන්නේ ඇයි?', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('77d1012f-585d-5428-9069-06589b26ce99', 'e03e75ba-c88e-5244-8d46-3a35a1b366dd', 31, '<p>තේ හැන්දෙන් එකක් ......... උදයට බොන්න.<br>ඈ ගැබිනියක ......... රඟ පෑවාය.<br>ජලගැල්ම ......... කුඹුරු විනාශ විය.<br>දේශය ගොඩ නැගීම ......... දායක වන්න.<br><br>ඉහත වාක්‍ය වල හිස්තැන් පිරවීම සඳහා වඩාත් යෝග්‍ය නිපාත පද අනුපිළිවෙළ කුමක්ද?</p>', '<p>තේ හැන්දෙන් එකක් ......... උදයට බොන්න.<br>ඈ ගැබිනියක ......... රඟ පෑවාය.<br>ජලගැල්ම ......... කුඹුරු විනාශ විය.<br>දේශය ගොඩ නැගීම ......... දායක වන්න.<br><br>ඉහත වාක්‍ය වල හිස්තැන් පිරවීම සඳහා වඩාත් යෝග්‍ය නිපාත පද අනුපිළිවෙළ කුමක්ද?</p>', NULL, 'එකක් පමණ (ප්‍රමාණය), ගැබිනියක මෙන් (උපමාව), ජලගැල්ම නිසා (හේතුව), ගොඩ නැගීම සඳහා (අරමුණ) ලෙස හිස්තැන් අනුපිළිවෙළට ගැළපේ.', 'එකක් පමණ (ප්‍රමාණය), ගැබිනියක මෙන් (උපමාව), ජලගැල්ම නිසා (හේතුව), ගොඩ නැගීම සඳහා (අරමුණ) ලෙස හිස්තැන් අනුපිළිවෙළට ගැළපේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
