INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('43f5482b-295f-5b5f-9fb2-f82543b43dcf', 'e03e75ba-c88e-5244-8d46-3a35a1b366dd', 34, '<p>වෙර වීරිය ඇතත් හිතේ<br>පියකරු බව ඇතත් වතේ<br>දහදිය නොම සැලෙන ගතේ<br>ඔබ පොළවට බරකි පුතේ<br><br>යන පද්‍යයේ අදහස නිවැරදි ව දැක්වෙන වරණය තෝරන්න.</p>', '<p>වෙර වීරිය ඇතත් හිතේ<br>පියකරු බව ඇතත් වතේ<br>දහදිය නොම සැලෙන ගතේ<br>ඔබ පොළවට බරකි පුතේ<br><br>යන පද්‍යයේ අදහස නිවැරදි ව දැක්වෙන වරණය තෝරන්න.</p>', NULL, 'සිතේ ධෛර්යය සහ මුහුණේ ලස්සන තිබුණත්, වෙහෙසී වැඩ කර දහදිය නොහෙළන්නේ නම් ඔහු මහපොළොවට බරක් වන බව පද්‍යයෙන් කියැවේ.', 'සිතේ ධෛර්යය සහ මුහුණේ ලස්සන තිබුණත්, වෙහෙසී වැඩ කර දහදිය නොහෙළන්නේ නම් ඔහු මහපොළොවට බරක් වන බව පද්‍යයෙන් කියැවේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2f4aa332-695a-4cda-a7a4-dda42c0cdc98', '43f5482b-295f-5b5f-9fb2-f82543b43dcf', 'ශරීර ශක්තියෙන් හා මුහුණේ පැහැපත් බවින් යුතු ව මහ පොළොවට බරක් නොවී රට වෙනුවෙන් ශ්‍රම දායකත්වය ලබාදිය යුතු බව', 'ශරීර ශක්තියෙන් හා මුහුණේ පැහැපත් බවින් යුතු ව මහ පොළොවට බරක් නොවී රට වෙනුවෙන් ශ්‍රම දායකත්වය ලබාදිය යුතු බව', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('85d55eea-8b72-4767-994a-360b7d02cdda', '43f5482b-295f-5b5f-9fb2-f82543b43dcf', 'ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව තිබුණ ද රට වෙනුවෙන් ශ්‍රම දායකත්වයක් සපයන්නේ නැති නම් ඔහුගෙන් පලක් නැති බව', 'ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව තිබුණ ද රට වෙනුවෙන් ශ්‍රම දායකත්වයක් සපයන්නේ නැති නම් ඔහුගෙන් පලක් නැති බව', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c5f33d1e-9b1c-4c3e-844e-82aca9ced4af', '43f5482b-295f-5b5f-9fb2-f82543b43dcf', 'රට වෙනුවෙන් ශ්‍රමය වැය කිරීම අනිවාර්යයෙන් කළ යුතු වුවත් ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව රැක ගත යුතු බව', 'රට වෙනුවෙන් ශ්‍රමය වැය කිරීම අනිවාර්යයෙන් කළ යුතු වුවත් ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව රැක ගත යුතු බව', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cead3a50-36a1-482e-9e84-37f36325431a', '43f5482b-295f-5b5f-9fb2-f82543b43dcf', 'මහ පොළොවට බරක් වන්නේ ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව රැක ගනිමින් ශ්‍රම දායකත්වය සැපයීම නොකළ විට බව', 'මහ පොළොවට බරක් වන්නේ ශරීර ශක්තිය හා මුහුණේ පැහැපත් බව රැක ගනිමින් ශ්‍රම දායකත්වය සැපයීම නොකළ විට බව', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('67c5a77b-0940-5226-a77e-16441613746a', 'e03e75ba-c88e-5244-8d46-3a35a1b366dd', 35, '<p>හුණුවටයේ කතාව නාට්‍යයේ ඇතුළත්,<br><br>''අප්ප උඹේ හොර දෙටුවා<br>අම්ම හරිම කුනකටුවා<br>ඒ හින්දා පුතේ උඹට<br>මුළු ලෝකෙම දණ නමාවී''<br><br>යන ගීය කියන්නේ,</p>', '<p>හුණුවටයේ කතාව නාට්‍යයේ ඇතුළත්,<br><br>''අප්ප උඹේ හොර දෙටුවා<br>අම්ම හරිම කුනකටුවා<br>ඒ හින්දා පුතේ උඹට<br>මුළු ලෝකෙම දණ නමාවී''<br><br>යන ගීය කියන්නේ,</p>', NULL, 'මෙම ගීතය ගායනා කරන්නේ හුණුවටයේ කතාව නාට්‍යයේ ප්‍රධාන චරිතයක් වන ගෲෂා විසිනි.', 'මෙම ගීතය ගායනා කරන්නේ හුණුවටයේ කතාව නාට්‍යයේ ප්‍රධාන චරිතයක් වන ගෲෂා විසිනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
