INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d0e0f7aa-fd2b-5c42-859c-8171bc7b5177', 'e5fb40b1-c0c0-5be2-a1e5-c76205ead825', 9, '<p>$4^4 \times 4^2$ සුළු කරන්න.</p>', '<p>$4^4 \times 4^2$ සුළු කරන්න.</p>', NULL, '<p>දර්ශක නීති වලට අනුව, $a^m \times a^n = a^{m+n}$. එබැවින් $4^4 \times 4^2 = 4^{4+2} = 4^6$.</p>', '<p>දර්ශක නීති වලට අනුව, $a^m \times a^n = a^{m+n}$. එබැවින් $4^4 \times 4^2 = 4^{4+2} = 4^6$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('34d46316-aef8-4a21-a9cf-81b9f2439bde', 'd0e0f7aa-fd2b-5c42-859c-8171bc7b5177', '$4^6$', '$4^6$', NULL, 'sanitized', 'v1', 0, 1);
