INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('412e4c00-283e-5d75-b620-bd5853bf02c2', 'e5fb40b1-c0c0-5be2-a1e5-c76205ead825', 26, '<p>ත්‍රිකෝණයක කෝණ දෙකක් 41^{\circ}$ සහ 51^{\circ}$ වේ. එහි තුන්වන කෝණයේ අගය සොයන්න.</p>', '<p>ත්‍රිකෝණයක කෝණ දෙකක් 41^{\circ}$ සහ 51^{\circ}$ වේ. එහි තුන්වන කෝණයේ අගය සොයන්න.</p>', NULL, '<p>ත්‍රිකෝණයක අභ්‍යන්තර කෝණවල ඓක්‍යය $180^{\circ}$ වේ. එබැවින් $180 - (41 + 51) = 88^{\circ}$.</p>', '<p>ත්‍රිකෝණයක අභ්‍යන්තර කෝණවල ඓක්‍යය $180^{\circ}$ වේ. එබැවින් $180 - (41 + 51) = 88^{\circ}$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
