INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('33e3b86e-5877-5ecf-8e76-d733018f4d0c', 'e5fb40b1-c0c0-5be2-a1e5-c76205ead825', 37, '<p>දිග 6 cm හා පළල 3 cm වූ සෘජුකෝණාස්‍රයක වර්ගඵලය සොයන්න.</p>', '<p>දිග 6 cm හා පළල 3 cm වූ සෘජුකෝණාස්‍රයක වර්ගඵලය සොයන්න.</p>', NULL, '<p>වර්ගඵලය = දිග $\times$ පළල = $6 \times 3 = 18 \text{ cm}^2$.</p>', '<p>වර්ගඵලය = දිග $\times$ පළල = $6 \times 3 = 18 \text{ cm}^2$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
