INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a301f7f4-4b13-5f12-8223-fe6e563efc83', 'ecd13524-358b-576f-9f41-1c8079f52be9', 11, '<p>How much is the mass of $NaCl$ contained in $100~cm^{3}$ of a sodium chloride solution of concentration $1.0~mol~dm^{-3}$?<br><br>($Na=23$, $Cl=35.5$)</p>', '<p>How much is the mass of $NaCl$ contained in $100~cm^{3}$ of a sodium chloride solution of concentration $1.0~mol~dm^{-3}$?<br><br>($Na=23$, $Cl=35.5$)</p>', NULL, 'Molar mass of $NaCl = 23 + 35.5 = 58.5~g~mol^{-1}$.<br>Number of moles in $100~cm^3$ = $(1.0~mol~dm^{-3}) \times (100 / 1000~dm^3) = 0.1~mol$.<br>Mass = Moles $\times$ Molar mass = $0.1 \times 58.5 = 5.85~g$.', 'Molar mass of $NaCl = 23 + 35.5 = 58.5~g~mol^{-1}$.<br>Number of moles in $100~cm^3$ = $(1.0~mol~dm^{-3}) \times (100 / 1000~dm^3) = 0.1~mol$.<br>Mass = Moles $\times$ Molar mass = $0.1 \times 58.5 = 5.85~g$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
