INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b6dbbb6e-1b3b-5666-8dcf-deb798d9dda5', 'ecd13524-358b-576f-9f41-1c8079f52be9', 15, '<p>What is the increasing order of pH of four solutions of $HCl$, $CH_{3}COOH$, $NaOH$ and $NH_{3}$ of equal concentration?</p>', '<p>What is the increasing order of pH of four solutions of $HCl$, $CH_{3}COOH$, $NaOH$ and $NH_{3}$ of equal concentration?</p>', NULL, '$HCl$ is a strong acid (lowest pH). $CH_3COOH$ is a weak acid. $NH_3$ is a weak base. $NaOH$ is a strong base (highest pH). Thus, the order from lowest to highest pH is $HCl < CH_{3}COOH < NH_{3} < NaOH$.', '$HCl$ is a strong acid (lowest pH). $CH_3COOH$ is a weak acid. $NH_3$ is a weak base. $NaOH$ is a strong base (highest pH). Thus, the order from lowest to highest pH is $HCl < CH_{3}COOH < NH_{3} < NaOH$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
