INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4da08e8c-280e-53c6-8d80-23e16473471a', 'ecd13524-358b-576f-9f41-1c8079f52be9', 16, '<p>What is the number of $CO_{2}$ molecules in 22 g of carbon dioxide?<br><br>($C=12$, $O=16$, Avogadro constant $= 6.022 \times 10^{23}~mol^{-1}$)</p>', '<p>What is the number of $CO_{2}$ molecules in 22 g of carbon dioxide?<br><br>($C=12$, $O=16$, Avogadro constant $= 6.022 \times 10^{23}~mol^{-1}$)</p>', NULL, 'Molar mass of $CO_2 = 12 + (2 \times 16) = 44~g~mol^{-1}$.<br>Number of moles = $\frac{Mass}{Molar~Mass} = \frac{22}{44}$.<br>Number of molecules = Moles $\times$ Avogadro''s constant = $\frac{22}{44} \times 6.022 \times 10^{23}$.', 'Molar mass of $CO_2 = 12 + (2 \times 16) = 44~g~mol^{-1}$.<br>Number of moles = $\frac{Mass}{Molar~Mass} = \frac{22}{44}$.<br>Number of molecules = Moles $\times$ Avogadro''s constant = $\frac{22}{44} \times 6.022 \times 10^{23}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
