INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1d9d5c45-c69d-58db-b1ed-1d595cf15c24', 'ecd13524-358b-576f-9f41-1c8079f52be9', 17, '<p>The chemical formula of the chemical fertilizer urea is $CO(NH_{2})_{2}$. Select the correct statement about urea.</p>', '<p>The chemical formula of the chemical fertilizer urea is $CO(NH_{2})_{2}$. Select the correct statement about urea.</p>', NULL, 'Analyzing the formula $CO(NH_2)_2$, there is 1 Carbon atom, 1 Oxygen atom, 2 Nitrogen atoms, and $2 \times 2 = 4$ Hydrogen atoms. Therefore, a molecule of urea has four hydrogen atoms.', 'Analyzing the formula $CO(NH_2)_2$, there is 1 Carbon atom, 1 Oxygen atom, 2 Nitrogen atoms, and $2 \times 2 = 4$ Hydrogen atoms. Therefore, a molecule of urea has four hydrogen atoms.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
