INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e67d2f94-e203-5848-8d40-24aab14d3572', 'ecd13524-358b-576f-9f41-1c8079f52be9', 18, '<p>Which option contains only the components that are found in the glomerular filtrate but not in urine of a healthy person?</p>', '<p>Which option contains only the components that are found in the glomerular filtrate but not in urine of a healthy person?</p>', NULL, 'In a healthy kidney, valuable nutrients like glucose and amino acids are filtered into the glomerular filtrate but are 100% reabsorbed into the blood in the proximal convoluted tubule, so they do not appear in the final urine.', 'In a healthy kidney, valuable nutrients like glucose and amino acids are filtered into the glomerular filtrate but are 100% reabsorbed into the blood in the proximal convoluted tubule, so they do not appear in the final urine.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
