INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('71a40765-b228-596c-aa10-43a13f4fcc2d', 'ecd13524-358b-576f-9f41-1c8079f52be9', 20, '<p>Select the correct statement regarding the circulation of blood in humans.</p>', '<p>Select the correct statement regarding the circulation of blood in humans.</p>', NULL, 'The left ventricle pumps oxygenated blood into the aorta to supply the entire body, acting as the primary pump for the systemic circulation. (Note: pulmonary artery carries deoxygenated blood, and veins bring blood TO the heart).', 'The left ventricle pumps oxygenated blood into the aorta to supply the entire body, acting as the primary pump for the systemic circulation. (Note: pulmonary artery carries deoxygenated blood, and veins bring blood TO the heart).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
