INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f90dbc5e-96e7-593d-bc13-481657a316a5', 'ecd13524-358b-576f-9f41-1c8079f52be9', 30, '<p>When thin iron wool is heated, it instantly burns. But though an iron nail is heated till red hot, it does not undergo a considerable change. What conclusion can be drawn from these observations?</p>', '<p>When thin iron wool is heated, it instantly burns. But though an iron nail is heated till red hot, it does not undergo a considerable change. What conclusion can be drawn from these observations?</p>', NULL, 'Iron wool has a significantly larger surface area-to-volume ratio compared to a solid iron nail. This increased surface exposure allows more oxygen molecules to react simultaneously, greatly increasing the reaction rate.', 'Iron wool has a significantly larger surface area-to-volume ratio compared to a solid iron nail. This increased surface exposure allows more oxygen molecules to react simultaneously, greatly increasing the reaction rate.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
