INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('18b9de66-7c19-5019-a4d7-3819e54dd02b', 'ecd13524-358b-576f-9f41-1c8079f52be9', 34, '<p>Which of the following statements is false about electroplating of iron?</p>', '<p>Which of the following statements is false about electroplating of iron?</p>', NULL, 'For high-quality, smooth, and adherent electroplating, a low concentration of metal ions in the electrolyte is generally preferred, alongside a controlled low current density.', 'For high-quality, smooth, and adherent electroplating, a low concentration of metal ions in the electrolyte is generally preferred, alongside a controlled low current density.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
