INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('db1cf02e-69d3-5af2-8851-07ca76eeb859', 'ecd13524-358b-576f-9f41-1c8079f52be9', 35, '<p>A conical flask containing aqueous hydrochloric acid is kept on a sensitive balance. Pieces of limestone were added to it in excess. Which of the following graphs indicates how the balance reading varies against time after the addition of limestone?</p>', '<p>A conical flask containing aqueous hydrochloric acid is kept on a sensitive balance. Pieces of limestone were added to it in excess. Which of the following graphs indicates how the balance reading varies against time after the addition of limestone?</p>', NULL, 'When limestone ($CaCO_3$) reacts with $HCl$, it produces $CO_2$ gas which escapes, causing the total mass to decrease. As reactants are used up, the reaction rate slows down, causing the mass loss to taper off until the reaction stops and mass becomes constant.', 'When limestone ($CaCO_3$) reacts with $HCl$, it produces $CO_2$ gas which escapes, causing the total mass to decrease. As reactants are used up, the reaction rate slows down, causing the mass loss to taper off until the reaction stops and mass becomes constant.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', 