INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0ff476c6-2496-5efe-acd4-b0b303272bca', 'ecd13524-358b-576f-9f41-1c8079f52be9', 36, '<p>The number of turns in the primary coil and the secondary coil of a transformer are $N_{p}$ and $N_{s}$ respectively. The voltage difference of the primary coil is $V_{p}$ and the voltage difference of the secondary coil is $V_{s}$. What is the correct relationship between the numbers of turns and the voltage differences?</p>', '<p>The number of turns in the primary coil and the secondary coil of a transformer are $N_{p}$ and $N_{s}$ respectively. The voltage difference of the primary coil is $V_{p}$ and the voltage difference of the secondary coil is $V_{s}$. What is the correct relationship between the numbers of turns and the voltage differences?</p>', NULL, 'In an ideal transformer, the ratio of the voltages across the primary and secondary coils is directly proportional to the ratio of the number of turns in their respective coils: $\frac{V_{p}}{V_{s}}=\frac{N_{p}}{N_{s}}$.', 'In an ideal transformer, the ratio of the voltages across the primary and secondary coils is directly proportional to the ratio of the number of turns in their respective coils: $\frac{V_{p}}{V_{s}}=\frac{N_{p}}{N_{s}}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b22d5a05-8172-44d2-b64e-74d0a76673a1', '0ff476c6-2496-5efe-acd4-b0b303272bca', '$\frac{V_{p}}{V_{s}}=\frac{N_{p}}{N_{s}}$', '$\frac{V_{p}}{V_{s}}=\frac{N_{p}}{N_{s}}$', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('631e706a-7a91-4e98-8617-76af69a7f56e', '0ff476c6-2496-5efe-acd4-b0b303272bca', '$\frac{V_{s}}{V_{p}}=\frac{N_{p}}{N_{s}}$', '$\frac{V_{s}}{V_{p}}=\frac{N_{p}}{N_{s}}$', NULL, 'sanitized', 'v1', 1, 0);
