INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('75a22435-ea78-4139-a6ae-66a068288e24', 'd8efc6b2-5523-59fe-b62b-51ec0cd4b9ce', 'සැම පරමාණුවකම න්‍යෂ්ටියේ අඩංගු නියුට්‍රෝන ගණන හා ප්‍රෝටෝන ගණන සමාන වේ.', 'සැම පරමාණුවකම න්‍යෂ්ටියේ අඩංගු නියුට්‍රෝන ගණන හා ප්‍රෝටෝන ගණන සමාන වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('168b8d50-526f-4ac6-8a70-635a498b0574', 'd8efc6b2-5523-59fe-b62b-51ec0cd4b9ce', 'වෙනස් මූලද්‍රව්‍ය පරමාණු දෙකක පරමාණුක ක්‍රමාංක සමාන විය හැකිය.', 'වෙනස් මූලද්‍රව්‍ය පරමාණු දෙකක පරමාණුක ක්‍රමාංක සමාන විය හැකිය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8b7790db-a104-4ab8-8a0c-1cc56e1a92c6', 'd8efc6b2-5523-59fe-b62b-51ec0cd4b9ce', 'එකම මූල ද්‍රව්‍යයේ වෙනස් ස්කන්ධ ක්‍රමාංක සහිත පරමාණු තිබිය හැකිය.', 'එකම මූල ද්‍රව්‍යයේ වෙනස් ස්කන්ධ ක්‍රමාංක සහිත පරමාණු තිබිය හැකිය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cf91c0be-6970-5177-b41e-bb326ce3ecc0', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 5, '<p>පහත සඳහන් ශාක පටක අතරින් සංකීර්ණ, ස්ථිර පටකයක් වන්නේ කුමක්ද?</p>', '<p>පහත සඳහන් ශාක පටක අතරින් සංකීර්ණ, ස්ථිර පටකයක් වන්නේ කුමක්ද?</p>', NULL, 'මෘදුස්තර, ස්ථූලකෝණාස්තර සහ දෘඪස්තර යනු සරල ස්ථිර පටක වේ. ශෛලමය (Xylem) සහ ප්ලෝයමය (Phloem) යනු සෛල වර්ග කිහිපයකින් සමන්විත සංකීර්ණ ස්ථිර පටක වේ.', 'මෘදුස්තර, ස්ථූලකෝණාස්තර සහ දෘඪස්තර යනු සරල ස්ථිර පටක වේ. ශෛලමය (Xylem) සහ ප්ලෝයමය (Phloem) යනු සෛල වර්ග කිහිපයකින් සමන්විත සංකීර්ණ ස්ථිර පටක වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
