INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5ba2f740-fbd0-5c7c-b6c4-e02769945a05', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 9, '<p>විෂමපෝෂීන් පමණක් අයත් වන රාජධානි වන්නේ,</p>', '<p>විෂමපෝෂීන් පමණක් අයත් වන රාජධානි වන්නේ,</p>', NULL, 'ෆන්ගයි (දිලීර) සහ ඇනිමාලියා (සත්ත්ව) රාජධානිවලට අයත් සියලුම ජීවීන් විෂමපෝෂීන් වේ. ප්ලාන්ටේ (ශාක) රාජධානිය සම්පූර්ණයෙන්ම ස්වයංපෝෂී වන අතර ප්‍රොටිස්ටා රාජධානියේ ස්වයංපෝෂී (ඇල්ගී) සහ විෂමපෝෂී යන දෙවර්ගයම සිටී.', 'ෆන්ගයි (දිලීර) සහ ඇනිමාලියා (සත්ත්ව) රාජධානිවලට අයත් සියලුම ජීවීන් විෂමපෝෂීන් වේ. ප්ලාන්ටේ (ශාක) රාජධානිය සම්පූර්ණයෙන්ම ස්වයංපෝෂී වන අතර ප්‍රොටිස්ටා රාජධානියේ ස්වයංපෝෂී (ඇල්ගී) සහ විෂමපෝෂී යන දෙවර්ගයම සිටී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f010acca-9c52-4ef7-a865-ab1e87bac8dc', '5ba2f740-fbd0-5c7c-b6c4-e02769945a05', 'ෆන්ගයි සහ ප්‍රොටිස්ටා ය.', 'ෆන්ගයි සහ ප්‍රොටිස්ටා ය.', NULL, 'sanitized', 'v1', 0, 1);
