INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b18af016-4be3-49e8-9080-82933cceaab5', '5ba2f740-fbd0-5c7c-b6c4-e02769945a05', 'ෆන්ගයි සහ ඇනිමාලියා ය.', 'ෆන්ගයි සහ ඇනිමාලියා ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b6a5e8e2-0bb3-57c8-97f1-0f4ee2c34f18', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 10, '<p>පොලිතීන්වල පුනරාවර්තන ඒකකය කුමක්ද?</p>', '<p>පොලිතීන්වල පුනරාවර්තන ඒකකය කුමක්ද?</p>', NULL, 'පොලිතීන් සෑදෙන්නේ එතීන් ($CH_2=CH_2$) ඒකාවයවික බහුඅවයවීකරණය වීමෙනි. එහිදී ද්විත්ව බන්ධනය බිඳී සෑදෙන පුනරාවර්තන ඒකකය (Repeating unit) වන්නේ $-CH_2-CH_2-$ වේ. $n$ යොදා දක්වන්නේ මුළු බහුඅවයවකයයි.', 'පොලිතීන් සෑදෙන්නේ එතීන් ($CH_2=CH_2$) ඒකාවයවික බහුඅවයවීකරණය වීමෙනි. එහිදී ද්විත්ව බන්ධනය බිඳී සෑදෙන පුනරාවර්තන ඒකකය (Repeating unit) වන්නේ $-CH_2-CH_2-$ වේ. $n$ යොදා දක්වන්නේ මුළු බහුඅවයවකයයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
