INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('51b634bb-9bc0-4c01-9f3e-a1d21c927f76', 'b6a5e8e2-0bb3-57c8-97f1-0f4ee2c34f18', '$-CH_2-CH_2-$', '$-CH_2-CH_2-$', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f489c9ed-7f65-461f-851b-dc73f4bb56c8', 'b6a5e8e2-0bb3-57c8-97f1-0f4ee2c34f18', '$[-CH_2-CH_2-]_n$', '$[-CH_2-CH_2-]_n$', NULL, 'sanitized', 'v1', 2, 0);
