INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f3c916bd-ebac-5bba-8c76-cbcb68c125dd', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 11, '<p>පූර්ණ අභ්‍යන්තර පරාවර්තනය මගින් පැහැදිලි කළ නොහැකි සංසිද්ධිය මින් කුමක්ද?</p>', '<p>පූර්ණ අභ්‍යන්තර පරාවර්තනය මගින් පැහැදිලි කළ නොහැකි සංසිද්ධිය මින් කුමක්ද?</p>', NULL, 'දේදුන්නක් හටගැනීම (සුදු ආලෝකය වර්ණවලට බෙදීම) ප්‍රධාන වශයෙන් අපකිරණය (Dispersion) සහ වර්තනය (Refraction) නිසා සිදුවේ. ප්‍රකාශ තන්තු, දියමන්ති බැබලීම සහ ඍජුකෝණී ප්‍රිස්ම මගින් කිරණ හැරවීම පූර්ණ අභ්‍යන්තර පරාවර්තනයට සෘජු නිදසුන් වේ.', 'දේදුන්නක් හටගැනීම (සුදු ආලෝකය වර්ණවලට බෙදීම) ප්‍රධාන වශයෙන් අපකිරණය (Dispersion) සහ වර්තනය (Refraction) නිසා සිදුවේ. ප්‍රකාශ තන්තු, දියමන්ති බැබලීම සහ ඍජුකෝණී ප්‍රිස්ම මගින් කිරණ හැරවීම පූර්ණ අභ්‍යන්තර පරාවර්තනයට සෘජු නිදසුන් වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('861d9386-18de-4e3f-afaf-5c8c829df56f', 'f3c916bd-ebac-5bba-8c76-cbcb68c125dd', 'ප්‍රකාශ තන්තු තුළින් ආලෝකය ගමන් කිරීම', 'ප්‍රකාශ තන්තු තුළින් ආලෝකය ගමන් කිරීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3b5efcea-ca9a-45f0-a07a-060786d6d1c5', 'f3c916bd-ebac-5bba-8c76-cbcb68c125dd', 'කපා ඔප දැමීම මඟින් දියමන්තිවල බැබලීම ඇති වීම', 'කපා ඔප දැමීම මඟින් දියමන්තිවල බැබලීම ඇති වීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('45ec81b7-d5a4-4170-a246-5b997049c3d7', 'f3c916bd-ebac-5bba-8c76-cbcb68c125dd', 'සුදු ආලෝකය වර්ණ වලට බෙදී දේදුන්න හට ගැනීම', 'සුදු ආලෝකය වර්ණ වලට බෙදී දේදුන්න හට ගැනීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('27d4dc5e-589e-493f-ac0c-d33275a431fb', 'f3c916bd-ebac-5bba-8c76-cbcb68c125dd', 'ඍජුකෝණී ප්‍රිස්මයක් මගින් ආලෝක කිරණයක් 90° කින් හැරවීම', 'ඍජුකෝණී ප්‍රිස්මයක් මගින් ආලෝක කිරණයක් 90° කින් හැරවීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f26f548d-23c3-5997-810d-da153d6d779d', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 12, '<p>පුෂ්පයක සංසේචන ක්‍රියාවලියෙන් පසුව සිදු වන විපර්යාසයක් වන්නේ මින් කුමක්ද?</p>', '<p>පුෂ්පයක සංසේචන ක්‍රියාවලියෙන් පසුව සිදු වන විපර්යාසයක් වන්නේ මින් කුමක්ද?</p>', NULL, 'සංසේචනයෙන් පසුව පුෂ්පයක ඩිම්බ (Ovules) බීජ බවටත්, ඩිම්බකෝෂය (Ovary) ඵලය බවටත් විකසනය වේ. ඩිම්බකෝෂ බිත්තිය ඵලාවරණය බවටත්, ඩිම්බාවරණ බීජාවරණ බවටත් පත් වේ.', 'සංසේචනයෙන් පසුව පුෂ්පයක ඩිම්බ (Ovules) බීජ බවටත්, ඩිම්බකෝෂය (Ovary) ඵලය බවටත් විකසනය වේ. ඩිම්බකෝෂ බිත්තිය ඵලාවරණය බවටත්, ඩිම්බාවරණ බීජාවරණ බවටත් පත් වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3de02e7c-ba1b-4857-81ae-07a5c4174a7c', 'f26f548d-23c3-5997-810d-da153d6d779d', 'ඩිම්බ කෝෂය ඵලාවරණය බවට පත් වීම', 'ඩිම්බ කෝෂය ඵලාවරණය බවට පත් වීම', NULL, 'sanitized', 'v1', 0, 1);
