INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('32618ef5-ea8d-46eb-8377-6f35924bc72f', 'f26f548d-23c3-5997-810d-da153d6d779d', 'මණිපත්‍ර බීජාවරණය බවට පත් වීම', 'මණිපත්‍ර බීජාවරණය බවට පත් වීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('31a0991f-f961-4cad-a960-6b424ea4aefa', 'f26f548d-23c3-5997-810d-da153d6d779d', 'ඩිම්බාවරණය ඵලාවරණය බවට පත් වීම', 'ඩිම්බාවරණය ඵලාවරණය බවට පත් වීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6bd5e83f-6353-5e36-bc62-9f6b4ff28326', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 13, '<p>සිනිඳු පේශි පටකයේ ලක්ෂණයක් නොවන්නේ පහත සඳහන් කුමක්ද?</p>', '<p>සිනිඳු පේශි පටකයේ ලක්ෂණයක් නොවන්නේ පහත සඳහන් කුමක්ද?</p>', NULL, 'සිනිඳු පේශි (Smooth muscles) පටකයේ සෛල තර්කුරූපී (දෙකෙළවර සිහින් වූ) හැඩයක් ගනී, ඒකන්‍යෂ්ටික වේ, තවද ඒවා අනිච්ඡානුගව ක්‍රියා කරයි. සිනිඳු පේශිවල හරස් විලේඛ (Striations) දැකගත නොහැක. හරස් විලේඛ ඇත්තේ කංකාල සහ හෘත් පේශිවල ය.', 'සිනිඳු පේශි (Smooth muscles) පටකයේ සෛල තර්කුරූපී (දෙකෙළවර සිහින් වූ) හැඩයක් ගනී, ඒකන්‍යෂ්ටික වේ, තවද ඒවා අනිච්ඡානුගව ක්‍රියා කරයි. සිනිඳු පේශිවල හරස් විලේඛ (Striations) දැකගත නොහැක. හරස් විලේඛ ඇත්තේ කංකාල සහ හෘත් පේශිවල ය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
