INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c62840a8-a0cf-54ad-a48f-37f1075755e6', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 17, '<p>පහත සංයෝග අතරින් ස්කන්ධය අනුව ඔක්සිජන් ප්‍රතිශතය 50%ක් වන සංයෝගය කුමක්ද?<br>$(H=1$, $C=12$, $N=14$, $O=16$, $Mg=24$, $Ca=40)$</p>', '<p>පහත සංයෝග අතරින් ස්කන්ධය අනුව ඔක්සිජන් ප්‍රතිශතය 50%ක් වන සංයෝගය කුමක්ද?<br>$(H=1$, $C=12$, $N=14$, $O=16$, $Mg=24$, $Ca=40)$</p>', NULL, 'මෙතනෝල් ($CH_3OH$) හි මවුලික ස්කන්ධය $= 12 + 3 + 16 + 1 = 32~gmol^{-1}$ වේ. එහි ඇති ඔක්සිජන් වල ස්කන්ධය $16~g$ කි. එබැවින් ඔක්සිජන් ප්‍රතිශතය $= (16 / 32) \times 100\% = 50\%$ වේ.', 'මෙතනෝල් ($CH_3OH$) හි මවුලික ස්කන්ධය $= 12 + 3 + 16 + 1 = 32~gmol^{-1}$ වේ. එහි ඇති ඔක්සිජන් වල ස්කන්ධය $16~g$ කි. එබැවින් ඔක්සිජන් ප්‍රතිශතය $= (16 / 32) \times 100\% = 50\%$ වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
