INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bf677e3c-2229-4f50-b1f4-7b11edb25185', 'b6c909f9-82ef-5234-b5dd-ee53f0bbd4f4', 'කළ යුතු කාර්ය ප්‍රමාණය අඩු වීම', 'කළ යුතු කාර්ය ප්‍රමාණය අඩු වීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('15b1e5c5-a14e-5c3f-9e65-a8d4554a39b5', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 19, '<p>පුරුෂ ප්‍රජනක පද්ධතියේ ශුක්‍රාණු නිපදවෙන්නේ,</p>', '<p>පුරුෂ ප්‍රජනක පද්ධතියේ ශුක්‍රාණු නිපදවෙන්නේ,</p>', NULL, 'පුරුෂ ප්‍රජනක පද්ධතියේ ප්‍රධාන අවයවය වන වෘෂණ (Testes) තුළ ශුක්‍රාණු ජනනය (නිපදවීම) සිදුවේ. ශුක්‍ර ආශයිකා සහ පුරස්ථ ග්‍රන්ථිය මගින් ශුක්‍ර තරලයට අවශ්‍ය ශ්‍රාවයන් නිපදවයි.', 'පුරුෂ ප්‍රජනක පද්ධතියේ ප්‍රධාන අවයවය වන වෘෂණ (Testes) තුළ ශුක්‍රාණු ජනනය (නිපදවීම) සිදුවේ. ශුක්‍ර ආශයිකා සහ පුරස්ථ ග්‍රන්ථිය මගින් ශුක්‍ර තරලයට අවශ්‍ය ශ්‍රාවයන් නිපදවයි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
