INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('75b74f65-daad-5446-a0ee-274dc6a5b46f', 'ee96bab2-f7ed-53a3-94bb-3697b5ddbbea', 20, '<p>පහත දැක්වෙන සියලුම අණු සම්බන්ධයෙන් සත්‍ය වන ප්‍රකාශය කුමක්ද?<br>$CO_{2}$, $NH_{3}$, $H_{2}O$</p>', '<p>පහත දැක්වෙන සියලුම අණු සම්බන්ධයෙන් සත්‍ය වන ප්‍රකාශය කුමක්ද?<br>$CO_{2}$, $NH_{3}$, $H_{2}O$</p>', NULL, '$CO_2$, $NH_3$ සහ $H_2O$ යන අණු තුනෙහිම ලුවිස් ව්‍යුහ ඇඳි විට, මධ්‍ය පරමාණුව වන C, N සහ O වටා පිළිවෙළින් බන්ධන යුගල සහ එකසර යුගල (ඇත්නම්) එකතුව ඉලෙක්ට්‍රෝන අෂ්ටකයක් (ඉලෙක්ට්‍රෝන 8ක්) සම්පූර්ණ වී පවතී.', '$CO_2$, $NH_3$ සහ $H_2O$ යන අණු තුනෙහිම ලුවිස් ව්‍යුහ ඇඳි විට, මධ්‍ය පරමාණුව වන C, N සහ O වටා පිළිවෙළින් බන්ධන යුගල සහ එකසර යුගල (ඇත්නම්) එකතුව ඉලෙක්ට්‍රෝන අෂ්ටකයක් (ඉලෙක්ට්‍රෝන 8ක්) සම්පූර්ණ වී පවතී.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3e7f664c-ce1d-4f2f-b8ec-0252d5399d94', '75b74f65-daad-5446-a0ee-274dc6a5b46f', 'අණුවල මධ්‍ය පරමාණුවේ ඉලෙක්ට්‍රෝන අෂ්ටකය සම්පූර්ණ වී ඇත.', 'අණුවල මධ්‍ය පරමාණුවේ ඉලෙක්ට්‍රෝන අෂ්ටකය සම්පූර්ණ වී ඇත.', NULL, 'sanitized', 'v1', 0, 1);
